test("whale roster -01: accession and roster signatures are independent — only a filing move is an amendment", () => {
  const fs = require("fs"), path = require("path");
  const pol = fs.readFileSync(path.join(__dirname, "..", "src", "poller.js"), "utf8");
  // 2026.08.19-03: the write moved into whaleSeasonBuildQ (one writer for every build path),
  // which sits ABOVE whaleSeasonMaybe — the slice starts at the season core so the pins read the
  // gate (in Maybe) AND the write (in BuildQ) together, which is the actual invariant.
  const fn = pol.slice(pol.indexOf("function whaleSeasonBuildQ("));
  const body = fn.slice(0, fn.indexOf("\n  async function"));
  assert.ok(/const accs = \{\}/.test(body) && /const rosterSig = /.test(body), "two inputs, tracked separately");
  assert.ok(/!legacy && !accMoved && !rosterMoved/.test(body),
    "EITHER changing reopens the build — a roster edit changes what the aggregate would say just as an amendment does");
  assert.ok(/k in had\.accs && had\.accs\[k\] !== accs\[k\]/.test(body),
    "accessions compare on the INTERSECTION: a flat signature moves whenever the roster does, which is why it can't answer 'did a filing change?'");
  // 2026.08.19-03: the amended write moved into whaleSeasonBuildQ (the ONE writer for every
  // build path) — the doctrine is unchanged, only accMoved may set it; the pin follows the code.
  assert.ok(/amended: had \? \(meta && meta\.accMoved \? 1 :/.test(body),
    "…and only that comparison sets `amended`, or every add/remove announces a filing that never landed");
  assert.ok(/const legacy = had && !had\.accs/.test(body), "hydrated pre-build blobs rebuild once to adopt the roster");
  // The roster edits must reach the build directly rather than waiting on whaleTick's cadence.
  for (const f of ["function whaleAdd(cik, name, nowArg)", "function whaleRm(keyRaw, nowArg)"])
    assert.ok(pol.includes(f), "clock-injectable roster edit missing: " + f);
  assert.equal(pol.split("whaleSeasonMaybe(nowArg || Date.now())").length - 1, 2,
    "both add and remove reopen the build; a route that omits nowArg still gets the real clock");
});

test("focus -03 (2026.08.18-02): the day's list retires at 00:00 UTC — weekends included, prior list kept", () => {
  const { createPoller } = require("../src/poller");
  const base = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null };
  const FRI = { day: "2026-08-14", utcDay: "2026-08-14", open: Date.UTC(2026, 7, 14, 13, 30),
    close: Date.UTC(2026, 7, 14, 20, 0), prevCloseT: Date.UTC(2026, 7, 13, 20, 0),
    frozenAt: Date.UTC(2026, 7, 14, 13, 30), late: 0, rows: [{ ticker: "NVDA" }, { ticker: "MU" }],
    cuts: [], filledAt: 0, fillNote: null, pvDiff: null };
  const boot = () => { let saved = null;
    const p = createPoller({ dex: "xyz", version: "test", log: () => {},
      store: { ...base, saveFocus: (d) => { saved = d; }, loadFocus: () => ({ state: JSON.parse(JSON.stringify(FRI)), prev: null }) } });
    p.hydrateFocusNow(Date.UTC(2026, 7, 14, 18, 0));   // boot inside the stamp's own UTC day
    return { p, saved: () => saved };
  };

  // Inside the same UTC day — including after the 16:00 ET cash close — the list stands.
  const a = boot();
  const T_CLOSE = Date.UTC(2026, 7, 14, 20, 30);     // 16:30 ET Fri, still 2026-08-14 UTC
  a.p.focusTickNow(T_CLOSE);
  assert.ok(a.p.getFocus(T_CLOSE).today, "the close does NOT retire the list — the boundary is 00:00 UTC, four hours later");
  // The tick legitimately writes here (the +1h fill lands an hour after the open) — what matters
  // is that the write still carries a live state rather than a retirement.
  assert.ok(!a.saved() || a.saved().state, "any write in-day still carries the stamp, not a retirement");

  // 00:00 UTC crosses (20:00 ET Friday): the list retires and the tab goes empty.
  const T_AFTER = Date.UTC(2026, 7, 15, 0, 1);
  a.p.focusTickNow(T_AFTER);
  const f = a.p.getFocus(T_AFTER);
  assert.equal(f.today, null, "the day's list is gone");
  assert.ok(f.prev && f.prev.day === "2026-08-14", "retired, not deleted — it lands behind the yesterday toggle");
  assert.deepEqual(f.prev.rows.map((r) => r.ticker), ["NVDA", "MU"], "…verbatim, exactly as stamped");
  assert.ok(a.saved() && a.saved().prev && !a.saved().state, "the retirement persisted, so a redeploy can't resurrect it");
  assert.equal(f.state, "cleared", "a stamped-then-retired day reads CLEARED, not 'stamping on the next tick'");

  // THE WEEKEND REGRESSION. Retirement runs before the session gate; the old tick returned early
  // on a day with no session, so a Friday list survived until Monday's stamp.
  const b = boot();
  const T_SAT = Date.UTC(2026, 7, 16, 3, 0);       // Sat 23:00 ET — no cash session that ET day
  b.p.focusTickNow(T_SAT);
  assert.equal(b.p.getFocus(T_SAT).today, null, "a no-session day still retires the previous list");
  assert.ok(b.p.getFocus(T_SAT).prev, "…keeping it reachable");

  // Re-ticking after retirement is idempotent: nothing left to retire, prev is not overwritten.
  const before = b.saved();
  const T_SAT2 = Date.UTC(2026, 7, 16, 4, 0);
  b.p.focusTickNow(T_SAT2);
  assert.equal(b.saved(), before, "no second write — retirement fires once per stamp, not once per tick");
  assert.ok(b.p.getFocus(T_SAT2).prev.day === "2026-08-14", "and the prior list is not clobbered by an empty one");
});

// ============================================================================================
// FOCUS -07 (build 2026.08.18-07): the 00:00 UTC retirement must not re-stamp, and the +1h freeze
// must not race the 1m writer.
//
// WHY THE -02 SUITE MISSED THIS. The retirement test above is behavioural and it passes — but its
// fixture universe is EMPTY (`loadAll: () => new Map()`, no seeded rows). At the boundary tick the
// retirement fires, the stamp gate is reached on the same tick with a null state, and stampFocus
// then returns on the candidate floor because there is nothing to stamp. The adjacent path was
// exercised and proved nothing. In production the universe holds 65 names and the identical tick
// minted a second FROZEN @ OPEN record from the 20:00 ET tape, over the top of the real 09:30 one.
// So the seeded rig is not incidental here: it IS the test.
// ============================================================================================
test("focus -07: the 00:00 UTC retirement retires and stops — it must never re-stamp from the evening tape", () => {
  const { p, OPEN, saved } = focus04Rig(FOCUS04_FULL);
  const CLOSE = Date.UTC(2026, 7, 14, 20, 0);          // Fri 2026-08-14 16:00 ET
  p.focusTickNow(OPEN + 60000);
  const real = p.getFocus(OPEN + 60000).today;
  assert.ok(real && real.rows.length, "the genuine 09:30 stamp lands first");
  assert.equal(real.frozenAt, OPEN + 60000, "…stamped at the open, not later");
  assert.equal(real.late, 0);

  // 00:00 UTC Saturday IS 20:00 ET Friday: focusRetire nulls the state, and the ET session for that
  // ET day opened ten and a half hours ago. This is the exact production tick.
  const BOUNDARY = Date.UTC(2026, 7, 15, 0, 1);
  assert.ok(BOUNDARY > CLOSE, "the retirement boundary sits AFTER the cash close — that is the hazard");
  p.focusTickNow(BOUNDARY);
  const f = p.getFocus(BOUNDARY);
  assert.equal(f.today, null, "no second record is minted from the evening tape");
  assert.equal(f.state, "cleared", "the day reads CLEARED — the state -02 introduced was unreachable until now");
  assert.ok(f.prev && f.prev.frozenAt === OPEN + 60000, "the genuine open stamp is what survives behind the toggle");
  assert.deepEqual(f.prev.rows.map((r) => r.ticker), real.rows.map((r) => r.ticker), "…verbatim, not re-selected");
  assert.ok(saved() && saved().prev && !saved().state, "and that is what persisted, so a redeploy cannot resurrect it");

  // Re-ticking through the rest of the ET day keeps refusing. A bound that only holds for one tick
  // is not a bound.
  for (const t of [BOUNDARY + 30 * 60000, BOUNDARY + 3 * 3600e3]) {
    p.focusTickNow(t);
    assert.equal(p.getFocus(t).today, null, "still refused at " + new Date(t).toISOString());
  }
});

test("focus -07: a phantom record is repaired at boot, and the real stamp is recovered rather than guessed", () => {
  const { createPoller } = require("../src/poller");
  const base = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null };
  const OPEN = Date.UTC(2026, 7, 14, 13, 30), CLOSE = Date.UTC(2026, 7, 14, 20, 0);
  const mk = (frozenAt, utcDay, tick, open) => ({ day: "2026-08-14", utcDay, open: open || OPEN, close: CLOSE,
    prevCloseT: Date.UTC(2026, 7, 13, 20, 0), frozenAt, late: frozenAt - OPEN > 90000 ? 1 : 0,
    rows: [{ ticker: tick }], cuts: [], filledAt: frozenAt, fillNote: null, pvDiff: null });
  const REAL = mk(OPEN + 11000, "2026-08-14", "NBIS");
  const PHANTOM = mk(Date.UTC(2026, 7, 15, 0, 0, 17), "2026-08-15", "SNDK");   // stamped 4h after its own close
  const NOW = Date.UTC(2026, 7, 15, 2, 0);      // Fri 22:00 ET — inside the phantom's UTC day, so it would otherwise be kept
  const boot = (blob) => { const p = createPoller({ dex: "xyz", version: "test", log: () => {},
    store: { ...base, saveFocus: () => {}, loadFocus: () => JSON.parse(JSON.stringify(blob)) } });
    p.hydrateFocusNow(NOW); return p.getFocus(NOW); };

  const a = boot({ state: PHANTOM, prev: REAL });
  assert.equal(a.today, null, "the phantom is never served as today's list");
  assert.ok(a.prev && a.prev.rows[0].ticker === "NBIS", "the genuine open stamp is promoted back out of the prior slot");
  assert.equal(a.prev.frozenAt, OPEN + 11000, "…the real one, identified by its own frozenAt, not by position");

  // Nothing to recover: the phantom still dies, and NO substitute is invented for it.
  const b = boot({ state: PHANTOM, prev: null });
  assert.equal(b.today, null, "the phantom dies whether or not a real record survives");
  assert.equal(b.prev, null, "an unrecoverable day stays a hole — never back-filled with the phantom itself");

  // A prior record from a DIFFERENT session is not the missing stamp. The hard case is one that
  // claims the same ET day and is still inside the current UTC day, so a day-string match would
  // promote it and it would render as today's list: recovery keys on the session's own `open`, and
  // only an exact match is the record the phantom was written over.
  const OTHER = mk(OPEN + 20000, "2026-08-15", "WDC", OPEN + 1);
  const c = boot({ state: PHANTOM, prev: OTHER });
  assert.equal(c.today, null, "a record for another session is never promoted into today's slot");
  assert.ok(c.prev && c.prev.rows[0].ticker === "WDC", "…it is left exactly where it was found");

  // A clean blob is untouched by the repair — it must not fire on honest records.
  const d = boot({ state: mk(OPEN + 11000, "2026-08-15", "NBIS"), prev: null });
  assert.ok(d.today && d.today.rows[0].ticker === "NBIS", "an in-day honest stamp still hydrates as today's list");
});

// The 10:30 freeze fired the instant the clock reached open+1h and captured whatever the 1m writer
// had flushed — 59 of 60 minutes, recorded as `bars: 59`, frozen forever.
function focus07LaneRig() {
  const { createPoller } = require("../src/poller");
  const base = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null };
  const OPEN = Date.UTC(2026, 7, 14, 13, 30), M = 60000;
  const bars = []; for (let i = 0; i < 60; i++) bars.push([OPEN + i * M, 100, 106, 94, 101, 1000]);
  const lane = { posted: 59 };            // how many 1m bars the writer has actually flushed
  const store = { ...base, saveFocus: () => {}, loadFocus: () => null, candlesEnabled: () => true,
    readCandles: () => [], readCandles1m: (c, lo, hi) => bars.slice(0, lane.posted).filter((k) => k[0] >= lo && k[0] <= hi) };
  const p = createPoller({ dex: "xyz", store, log: () => {}, version: "test" });
  const spine = (px) => { const o = []; for (let i = 48; i >= 0; i--) o.push({ t: OPEN - i * 3600e3, o: px, h: px * 1.01, l: px * 0.99, c: px, v: 1e6 }); return o; };
  for (const [t, px] of [["BE", 100], ["NVDA", 900], ["MU", 100], ["AMD", 150], ["LLY", 800],
    ["TSLA", 300], ["XOM", 110], ["JPM", 200], ["COIN", 250], ["PLTR", 60]])
    p.seedRowNow("xyz:" + t, { ticker: t, uni: "xyz", px, vol: 9e6, oi: 9e6, oiBase: 1000, hourlyRaw: spine(px) });
  p.focusTickNow(OPEN + 5 * M);
  return { p, OPEN, M, lane };
}

test("focus -07: the +1h freeze holds for the last 1m bar instead of freezing a 59-minute hour", () => {
  const { p, OPEN, M, lane } = focus07LaneRig();
  assert.ok(p.getFocus(OPEN + 5 * M).today, "the stamp lands");

  p.focusTickNow(OPEN + 61 * M);
  assert.equal(p.getFocus(OPEN + 61 * M).today.filledAt, 0,
    "a 59-of-60 hour does NOT freeze — the writer is one bar behind, which is not the same as done");
  assert.ok(p.getFocus(OPEN + 61 * M).forming, "…and the columns keep reading FORMING while it waits");

  lane.posted = 60;                       // the 10:29 bar lands
  p.focusTickNow(OPEN + 62 * M);
  const rec = p.getFocus(OPEN + 62 * M).today;
  assert.ok(rec.filledAt, "the freeze lands once the hour is complete");
  assert.equal(rec.fillNote, null, "a complete hour claims no shortfall");
  for (const r of rec.rows) {
    assert.equal(r.h1.bars, 60, "the frozen geometry is measured over all sixty minutes");
    assert.equal(r.h1cov.inWin, 60, "…and the record says so, per seat");
    assert.equal(r.h1cov.mins, 60);
  }
});

test("focus -07: the grace is bounded — a lane that never completes still freezes, and discloses", () => {
  const { p, OPEN, M, lane } = focus07LaneRig();
  assert.equal(lane.posted, 59, "the writer stalls one bar short for good");
  p.focusTickNow(OPEN + 61 * M);
  assert.equal(p.getFocus(OPEN + 61 * M).today.filledAt, 0, "held inside the grace");
  p.focusTickNow(OPEN + 66 * M);          // past +1h +5m
  const rec = p.getFocus(OPEN + 66 * M).today;
  assert.ok(rec.filledAt, "the wait is bounded — the record freezes rather than staying forming all day");
  assert.match(rec.fillNote, /short of 60 1m bars/, "…and states the shortfall instead of implying a full hour");
  for (const r of rec.rows) assert.equal(r.h1cov.inWin, 59, "the per-seat count is the honest one");
});

test("focus -03: 'cleared' and 'pending' are different claims and must not collapse", () => {
  const { createPoller } = require("../src/poller");
  const { etDayStr: etDS } = require("../src/compute");
  const base = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null };
  const NOW = Date.UTC(2026, 7, 14, 22, 0);   // 18:00 ET Friday: after the close, BEFORE the 00:00 UTC boundary
  const today = etDS(NOW);
  const mk = (day, utcDay) => ({ day, utcDay, open: 1, close: 2, prevCloseT: 0, frozenAt: NOW - 40 * 3600e3,
    late: 0, rows: [{ ticker: "NVDA" }], cuts: [], filledAt: 0 });
  // A record for TODAY'S session that has already been retired: nothing more is coming today.
  const p = createPoller({ dex: "xyz", version: "test", log: () => {},
    store: { ...base, saveFocus: () => {}, loadFocus: () => ({ state: null, prev: mk(today, "1970-01-01") }) } });
  p.hydrateFocusNow(NOW);
  assert.equal(p.getFocus(NOW).state, "cleared",
    "today was stamped and retired — saying 'stamping on the next tick' would promise a list that is never coming");
  // No record at all for today: the open may genuinely still be pending.
  const q = createPoller({ dex: "xyz", version: "test", log: () => {},
    store: { ...base, saveFocus: () => {}, loadFocus: () => ({ state: null, prev: mk("2020-01-02", "2020-01-02") }) } });
  q.hydrateFocusNow(NOW);
  assert.notEqual(q.getFocus(NOW).state, "cleared", "a prior day's record must not make TODAY look already-retired");
});

test("focus -03: the prior list renders only when asked, and the toggle survives the clear", () => {
  const fs = require("fs"), path = require("path");
  const app = fs.readFileSync(path.join(__dirname, "..", "public", "app.js"), "utf8");
  const fn = app.slice(app.indexOf("function renderFocus()"));
  const body = fn.slice(0, fn.indexOf("\nfunction "));
  const pick = body.slice(body.indexOf("const day="), body.indexOf("\n  if(!FOC.showPrev"));
  assert.ok(/const day=FOC\.showPrev\?\(d\.prev\|\|null\):\(d\.today\|\|null\);/.test(pick),
    "no implicit fallback to d.prev — an empty list is a true statement about the day, a substituted one is not");
  assert.ok(!/d\.state==='pre'/.test(pick) && !/d\.state==='offday'/.test(pick),
    "the pre/offday auto-substitution is gone from the selection expression entirely");
  assert.ok(!body.includes("usingPrevAuto"), "…and so is the banner that narrated it");
  const bar = body.slice(body.indexOf('id="focprev"') - 200, body.indexOf('id="focprev"') + 120);
  assert.ok(/\+\(d\.prev\?/.test(bar) && !/d\.prev&&d\.today\?/.test(bar),
    "the toggle is gated on d.prev ALONE: gating on d.today removes it exactly when the clear makes it the only route back");
  assert.ok(/d\.state==='cleared'/.test(app) && /00:00 UTC/.test(app), "the cleared state renders its own line");
  const empty = body.slice(body.indexOf("if(!day){"), body.indexOf("if(!day){") + 700);
  assert.ok(/d\.state==='cleared'\?/.test(empty) && /d\.state==='offday'\?/.test(empty),
    "the empty-state copy names the state that produced it rather than one generic message");
});

test("focus -03: retirement is one producer and runs ahead of the session gate", () => {
  const fs = require("fs"), path = require("path");
  const pol = fs.readFileSync(path.join(__dirname, "..", "src", "poller.js"), "utf8");
  const fn = pol.slice(pol.indexOf("function focusTick(nowInj)"));
  const body = fn.slice(0, fn.indexOf("\n  function getFocus"));
  const retireAt = body.indexOf("focusRetire(now)"), sessAt = body.indexOf("if (!sess)");
  assert.ok(retireAt > 0 && sessAt > 0 && retireAt < sessAt,
    "retirement must precede the no-session early return, or a Friday list survives the whole weekend");
  assert.ok(!/focusPrev = focusState/.test(pol.slice(pol.indexOf("function stampFocus("), pol.indexOf("function fillFocus("))),
    "stampFocus no longer rolls the list — focusRetire is the single producer of retirement");
  assert.equal(pol.split("focusPrev = focusState;").length - 1, 1, "exactly one place in the file retires a stamp");
  assert.ok(/utcDay: focusUtcDayStr\(now\)/.test(pol), "the stamp records the UTC day it belongs to");
  assert.ok(/\(st && st\.utcDay\) \|\| \(st \? focusUtcDayStr\(st\.frozenAt \|\| st\.open\) : null\)/.test(pol),
    "pre-build blobs derive their shelf life from frozenAt — the migration, pinned");
});

// ============================================================================================
// FOCUS -04 (build 2026.08.18-03): operator-set liquidity floors.
// "Anything under X is untradeable at my size." Two walls (24h notional, open interest) applied
// at CANDIDATE ASSEMBLY, before loudness is ever compared, so the 09:00 preview and the 09:30
// stamp meet the identical filter. Behavioral tests execute the real gate and the real stamp
// path against seeded universes (-84 doctrine); manifest pins then hold the wiring.
// ============================================================================================
const { focusLimits, focusFloorFail, focusGate, FOCUS_HARD_VOL, FOCUS_HARD_OI, FOCUS_BELOW_N } = require("../src/compute");

test("focus -04: the limits sanitizer clamps to the backstop — a bad write can loosen nothing", () => {
  assert.deepEqual(focusLimits(null), { vol: FOCUS_HARD_VOL, oi: FOCUS_HARD_OI }, "absent config = the hard backstop, never an open wall");
  assert.deepEqual(focusLimits({}), { vol: FOCUS_HARD_VOL, oi: FOCUS_HARD_OI }, "empty object degrades the same way");
  assert.deepEqual(focusLimits({ vol: 5e6, oi: 750000 }), { vol: 5e6, oi: 750000 }, "an honest pair passes through");
  assert.deepEqual(focusLimits({ vol: "5000000", oi: "750000" }), { vol: 5e6, oi: 750000 }, "numeric strings (a JSON round-trip, a form post) coerce");
  // THE FAILURE MODE THIS CLAMP EXISTS FOR: NaN comparisons are all false, so a NaN floor would
  // have passed EVERY name and silently disabled the wall rather than tightening it.
  assert.deepEqual(focusLimits({ vol: NaN, oi: NaN }), { vol: FOCUS_HARD_VOL, oi: FOCUS_HARD_OI }, "NaN degrades to the backstop, never to an open wall");
  assert.deepEqual(focusLimits({ vol: "abc", oi: {} }), { vol: FOCUS_HARD_VOL, oi: FOCUS_HARD_OI }, "garbage degrades identically");
  assert.deepEqual(focusLimits({ vol: -1, oi: -1 }), { vol: FOCUS_HARD_VOL, oi: FOCUS_HARD_OI }, "negatives cannot dig under the backstop");
  assert.deepEqual(focusLimits({ vol: 1000, oi: 0 }), { vol: FOCUS_HARD_VOL, oi: FOCUS_HARD_OI }, "a floor BELOW the backstop resolves to the backstop — effective floor is max(hard, yours)");
  assert.equal(focusLimits({ vol: 5e6 + 0.7 }).vol, 5000001, "floors are whole dollars");
  assert.deepEqual(focusLimits(focusLimits({ vol: 5e6, oi: 750000 })), { vol: 5e6, oi: 750000 }, "idempotent — re-sanitizing a sanitized pair is a no-op");
});

test("focus -04: a missing OI read never fails the OI floor — refusing on a number we do not have is fabrication", () => {
  const L = { vol: 1e6, oi: 1e6 };
  assert.equal(focusFloorFail({ ticker: "A", vol: 9e6, oi: 9e6 }, L), null, "clears both");
  assert.equal(focusFloorFail({ ticker: "B", vol: 1e5, oi: 9e6 }, L), "vol", "thin tape");
  assert.equal(focusFloorFail({ ticker: "C", vol: 9e6, oi: 1e5 }, L), "oi", "thin book");
  assert.equal(focusFloorFail({ ticker: "D", vol: 1e5, oi: 1e5 }, L), "both", "both walls, disclosed as both");
  // The honest-null contract, matching the OI Δ column: absent is not zero.
  assert.equal(focusFloorFail({ ticker: "E", vol: 9e6, oi: null }, L), null, "null OI CLEARS the OI wall — the volume wall still judges it");
  assert.equal(focusFloorFail({ ticker: "F", vol: 9e6 }, L), null, "an absent oi field behaves the same as an explicit null");
  assert.equal(focusFloorFail({ ticker: "G", vol: 1e5, oi: null }, L), "vol", "…and a null-OI name can still fail on volume alone, never 'both'");
  assert.equal(focusFloorFail({ ticker: "H", vol: 9e6, oi: NaN }, L), null, "an unusable OI number is an absence, not a zero");
  // Boundary: the floor is a floor, not a strict inequality — a name AT the wall clears it.
  assert.equal(focusFloorFail({ ticker: "I", vol: 1e6, oi: 1e6 }, L), null, "exactly at both walls clears");
  assert.equal(focusFloorFail({ ticker: "J", vol: 1e6 - 1, oi: 1e6 }, L), "vol", "one dollar under does not");
  // A candidate with no volume at all is refused, not admitted by an undefined comparison.
  assert.equal(focusFloorFail({ ticker: "K" }, L), "vol", "a name with no volume read is refused on volume");
});

test("focus -04: focusGate splits cleared from refused, loudest-first, with the multiple the floor must fall by", () => {
  const mk = (t, vol, oi, gs) => ({ ticker: t, vol, oi, gapSigma: gs, cluster: "X" });
  const cands = [mk("PASS1", 9e6, 9e6, 1), mk("QUIET", 1e5, 9e6, 0.2), mk("LOUD", 1e5, 9e6, 3.5),
    mk("BOOK", 9e6, 1e5, 1.5), mk("NOOI", 9e6, null, 2), mk("BOTH", 5e5, 5e5, 2.5)];
  const g = focusGate(cands, { vol: 1e6, oi: 1e6 });
  assert.deepEqual(g.pass.map((c) => c.ticker), ["PASS1", "NOOI"], "cleared keeps candidate order — the caller ranks, the gate does not");
  assert.equal(g.scanned, 6, "scanned counts the whole field the wall judged");
  assert.equal(g.belowN, 4, "belowN is the TRUE refused count, not the disclosed slice");
  // Loudest-first is the whole point: the top row is the loudest thing the wall is refusing.
  assert.deepEqual(g.below.map((c) => c.ticker), ["LOUD", "BOTH", "BOOK", "QUIET"], "refused set is ordered by loudness, not alphabetically");
  const by = (t) => g.below.find((c) => c.ticker === t);
  assert.equal(by("LOUD").why, "vol"); assert.equal(by("BOOK").why, "oi"); assert.equal(by("BOTH").why, "both");
  assert.equal(by("LOUD").need, 10, "the volume floor would have to fall 10× to admit LOUD");
  assert.equal(by("BOOK").need, 10, "the OI floor would have to fall 10× to admit BOOK");
  assert.equal(by("BOTH").need, 2, "a both-fail reports the BINDING wall (the larger drop), never the easier one");
  assert.ok(g.below.every((c) => typeof c.score === "number"), "loudness rides along so the roster can show what it is refusing");
  assert.deepEqual(g.limits, { vol: 1e6, oi: 1e6 }, "the gate reports the wall it actually applied");
  // The disclosed roster is capped; the count is not.
  const many = Array.from({ length: 40 }, (_, i) => mk("T" + String(i).padStart(2, "0"), 1e5, 9e6, 1));
  const g2 = focusGate(many, { vol: 1e6, oi: 0 });
  assert.equal(g2.below.length, FOCUS_BELOW_N, "roster discloses the loudest N");
  assert.equal(g2.belowN, 40, "…while the count stays honest about the whole tail");
  assert.equal(focusGate(many, { vol: 1e6, oi: 0 }, 3).below.length, 3, "N is honoured");
  // Degenerates: a gate is a filter, never a thrower.
  assert.deepEqual(focusGate(null, null).pass, [], "null candidate list degrades");
  assert.deepEqual(focusGate([{ nope: 1 }, null, { ticker: "" }], null).pass, [], "malformed candidates are dropped, never thrown on");
  // No floors set (the backstop only) must still refuse a genuinely untradeable name.
  const g3 = focusGate([mk("DUST", 1000, 1000, 3)], null);
  assert.equal(g3.pass.length, 0, "the backstop still bites when no operator floor is set");
});

// ---- engine harness: the floors against the REAL stamp path ---------------------------------
// Seeded universe -> real focusTick -> real focusCandidates -> real focusGate -> real focusSelect.
// Ticker choice is load-bearing: classification resolves off the real sector map, so a made-up
// symbol is dropped as non-Equity before the wall is ever consulted and would silently prove
// nothing about the gate.
function focus04Rig(cfg, opts) {
  const { createPoller } = require("../src/poller");
  const base = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null };
  let saved = null;
  const p = createPoller({ dex: "xyz", version: "test", log: () => {},
    store: { ...base, saveFocus: (d) => { saved = d; }, loadFocus: () => (opts && opts.load ? opts.load : null) } });
  const OPEN = Date.UTC(2026, 7, 14, 13, 30), H = 3600 * 1000;   // Fri 2026-08-14, 09:30 ET
  const spine = (px) => { const o = []; for (let i = 48; i >= 0; i--) o.push({ t: OPEN - i * H, o: px, h: px * 1.01, l: px * 0.99, c: px, v: 1e6 }); return o; };
  Object.entries(cfg).forEach(([t, [vol, oi]], i) =>
    p.seedRowNow("xyz:" + t, { ticker: t, uni: "xyz", px: 100 + i, vol, oi, oiBase: 1000, hourlyRaw: spine(100 + i) }));
  return { p, OPEN, saved: () => saved };
}
const FOCUS04_FULL = { NVDA: [9e6, 5e6], MU: [9e6, 5e6], AMD: [9e6, 5e6], LLY: [9e6, 5e6], TSLA: [9e6, 5e6],
  XOM: [9e6, 5e6], JPM: [9e6, 5e6], COIN: [9e6, 1e5], PLTR: [9e6, null], SNOW: [3e5, 9e6] };
// GRADED depths, for the tests where the wall has to actually bite: only three names sit above
// $20M, the rest are ordinary names an institutional clip cannot work. A flat fixture would let a
// "strict" wall pass everything and the test would assert nothing.
const FOCUS04_GRADED = { NVDA: [40e6, 9e6], MU: [30e6, 9e6], AMD: [22e6, 9e6], LLY: [9e6, 9e6],
  TSLA: [8e6, 9e6], XOM: [6e6, 9e6], JPM: [5e6, 9e6], COIN: [4e6, 1e5], PLTR: [9e6, null], SNOW: [3e5, 9e6] };

test("focus -04: the floors gate a real stamp, and the record freezes the wall that cut it", () => {
  const { p, OPEN } = focus04Rig(FOCUS04_FULL);
  assert.deepEqual(p.setFocusLimits(5e6, 1e6, false), { ok: false, error: "forbidden" }, "a non-admin write is refused outright");
  assert.deepEqual(p.getFocusLimits().limits, { vol: FOCUS_HARD_VOL, oi: FOCUS_HARD_OI }, "…and changes nothing");
  assert.deepEqual(p.setFocusLimits(1000, -5, true).limits, { vol: FOCUS_HARD_VOL, oi: FOCUS_HARD_OI }, "an admin write below the backstop resolves TO the backstop");
  assert.deepEqual(p.setFocusLimits(5e6, 1e6, true).limits, { vol: 5e6, oi: 1e6 }, "an honest write lands");

  p.focusTickNow(OPEN + 60000);
  const f = p.getFocus(OPEN + 60000);
  const rec = f.today;
  assert.ok(rec, "the stamp lands");
  assert.equal(rec.cleared, 8, "eight names cleared the wall");
  assert.equal(rec.scanned, 10, "…out of the ten structurally eligible");
  assert.equal(rec.belowN, 2, "two were refused on size");
  assert.deepEqual(rec.below.map((b) => b.ticker + ":" + b.why), ["COIN:oi", "SNOW:vol"], "each refusal names the wall it hit");
  assert.equal(rec.below.find((b) => b.ticker === "SNOW").need, 16.7, "the roster states how far the floor must fall to admit it");
  // THE OI CONTRACT, end to end: PLTR carries no OI read and seats anyway.
  assert.ok(rec.rows.some((r) => r.ticker === "PLTR"), "a name with no honest OI read takes a seat — it is never refused on a number we do not have");
  assert.ok(!rec.rows.some((r) => r.ticker === "COIN" || r.ticker === "SNOW"), "refused names hold no seat");
  assert.ok(!(rec.cuts || []).some((c) => c.ticker === "COIN" || c.ticker === "SNOW"),
    "…and they are NOT cuts: cuts lost the ranking, these never entered it — collapsing the two would hide which mechanism refused them");
  assert.ok(rec.rows.every((r) => r.oi === null || r.oi >= 1e6), "every seated row carries the OI notional the wall judged");
  assert.deepEqual(rec.limits, { vol: 5e6, oi: 1e6 }, "the wall in force at the stamp is written ONTO the record");

  // IMMUTABILITY: raising the floors afterwards must not rewrite how this list was made.
  p.setFocusLimits(50e6, 40e6, true);
  const f2 = p.getFocus(OPEN + 120000);
  assert.deepEqual(f2.today.limits, { vol: 5e6, oi: 1e6 }, "the frozen record still states the wall it was cut with");
  assert.equal(f2.today.rows.length, 6, "…and still holds its six seats");
  assert.deepEqual(f2.today.below.map((b) => b.ticker), ["COIN", "SNOW"], "…and its refused roster is the one from the stamp, not from today's panel value");
  assert.deepEqual(f2.limits, { vol: 50e6, oi: 40e6 }, "the LIVE wall is a separate field — what the next stamp will use");
  assert.deepEqual(f2.hard, { vol: FOCUS_HARD_VOL, oi: FOCUS_HARD_OI }, "the backstop ships so the panel can state what it cannot go under");
});

test("focus -04: a strict wall stamps SHORT — never padded, never mistaken for a booting universe", () => {
  // THE SPLIT. One count served both roles before this build: the booting check and the seating
  // check. A strict wall was therefore indistinguishable from a cold universe — the tick deferred,
  // the stamp never landed, and the tab read "pending" all day with no statement of why.
  // 1) genuinely booting (five eligible names, pre-floor) -> defer, no record.
  const boot = focus04Rig({ NVDA: [9e6, 9e6], MU: [9e6, 9e6], AMD: [9e6, 9e6], LLY: [9e6, 9e6], TSLA: [9e6, 9e6] });
  boot.p.focusTickNow(boot.OPEN + 60000);
  assert.equal(boot.p.getFocus(boot.OPEN + 60000).today, null, "a booting universe still defers — something IS coming, and a phantom list would deny it");
  assert.equal(boot.saved(), null, "…and nothing is persisted");
  // 2) a full field behind a strict wall -> stamp what cleared, however few. Graded volumes so
  //    the wall genuinely bites: only NVDA/MU/AMD sit above $20M, the rest are ordinary names the
  //    operator's clip cannot work. Ten eligible (past the booting floor), three cleared.
  const strict = focus04Rig(FOCUS04_GRADED);
  strict.p.setFocusLimits(20e6, 4.5e6, true);
  strict.p.focusTickNow(strict.OPEN + 60000);
  const rec = strict.p.getFocus(strict.OPEN + 60000).today;
  assert.ok(rec, "a strict wall does NOT defer — the field is there, the operator's size is the reason it is thin");
  assert.ok(rec.rows.length < 6 && rec.rows.length > 0, "the list is short, not empty and not padded");
  assert.equal(rec.rows.length, rec.cleared, "with fewer cleared names than seats, every cleared name seats");
  assert.equal(rec.scanned, 10, "the record discloses the pre-floor field so 'short' is readable as a choice, not a gap");
  assert.ok(rec.cleared < 6, "…and how few cleared it");
  assert.equal(rec.rows.length, 3, "exactly the three names that clear the wall");
  assert.ok(rec.rows.every((r) => r.vol >= 20e6), "every seat clears the volume wall");
  assert.ok(rec.rows.every((r) => r.oi === null || r.oi >= 4.5e6), "every seat clears the OI wall or carries no OI read");
  // 3) idempotence: the day is stamped, so a later tick must not re-cut it against the same wall.
  const before = JSON.stringify(rec);
  strict.p.focusTickNow(strict.OPEN + 90000);
  assert.equal(JSON.stringify(strict.p.getFocus(strict.OPEN + 90000).today), before, "a stamped day is stamped once — the tick does not re-cut it");
});

test("focus -04: preview and stamp meet the IDENTICAL wall, and a floor change busts the preview", () => {
  const { p, OPEN } = focus04Rig(FOCUS04_GRADED);
  p.setFocusLimits(5e6, 1e6, true);
  const PRE = OPEN - 15 * 60 * 1000;              // 09:15 ET — inside the preview lead
  p.focusTickNow(PRE);
  const pv = p.getFocus(PRE).preview;
  assert.ok(pv, "the prep pool builds");
  assert.ok(!pv.rows.some((r) => r.ticker === "COIN" || r.ticker === "SNOW"),
    "the pool is gated by the SAME wall the stamp will use — prepping against names the bell will refuse is the drift this prevents");
  assert.ok(pv.rows.some((r) => r.ticker === "PLTR"), "…including the missing-OI rule");
  assert.equal(pv.cleared, 8, "the pool discloses how many cleared");
  assert.equal(pv.scanned, 10, "…out of how many were eligible");
  assert.deepEqual(pv.below.map((b) => b.ticker), ["COIN", "SNOW"], "…and which names it is refusing, live");
  assert.deepEqual(pv.limits, { vol: 5e6, oi: 1e6 }, "the pool states the wall it applied");
  // A floor change must republish the pool even if the visible ten survive it: the ETag rides a
  // signature, and a wall the payload does not mention is a wall the client cannot show.
  const ver = p.getFocusStamp();
  p.setFocusLimits(20e6, 4.5e6, true);
  assert.notEqual(p.getFocusStamp(), ver, "the write bumps the stamp so the client's poll picks the new wall up");
  assert.equal(p.getFocus(PRE).preview, null, "the write drops the stale pool rather than serving one gated on the old wall");
  p.focusTickNow(PRE + 30000);
  const pv2 = p.getFocus(PRE + 30000).preview;
  assert.ok(pv2 && pv2.cleared === 3, "…and the next tick rebuilds it against the new one");
  assert.deepEqual(pv2.rows.map((r) => r.ticker), ["AMD", "MU", "NVDA"], "only the names that clear the deeper wall survive the rebuild");
  assert.deepEqual(pv2.limits, { vol: 20e6, oi: 4.5e6 }, "the rebuilt pool states the new wall");
});

test("focus -04: the floors survive a redeploy, and a corrupt blob cannot open the wall", () => {
  const stamp = { day: "2026-08-14", utcDay: "2026-08-14", open: Date.UTC(2026, 7, 14, 13, 30),
    close: Date.UTC(2026, 7, 14, 20, 0), prevCloseT: 0,
    frozenAt: Date.UTC(2026, 7, 14, 13, 30), late: 0, rows: [{ ticker: "NVDA" }], cuts: [], filledAt: 0,
    limits: { vol: 5e6, oi: 1e6 }, scanned: 10, cleared: 8, below: [], belowN: 2 };
  const a = focus04Rig({}, { load: { state: stamp, prev: null, limits: { vol: 5e6, oi: 1e6 } } });
  a.p.hydrateFocusNow(Date.UTC(2026, 7, 14, 18, 0));
  assert.deepEqual(a.p.getFocusLimits().limits, { vol: 5e6, oi: 1e6 }, "the wall rides the same blob as the record — one atomic write, restored together");
  assert.deepEqual(a.p.getFocus(Date.UTC(2026, 7, 14, 18, 0)).today.limits, { vol: 5e6, oi: 1e6 }, "…and the restored record still states its own wall");
  // A hand-edited or truncated blob must fail CLOSED (to the backstop), never open.
  const b = focus04Rig({}, { load: { state: stamp, prev: null, limits: { vol: NaN, oi: "open sesame" } } });
  b.p.hydrateFocusNow(Date.UTC(2026, 7, 14, 18, 0));
  assert.deepEqual(b.p.getFocusLimits().limits, { vol: FOCUS_HARD_VOL, oi: FOCUS_HARD_OI }, "corrupt floors degrade to the backstop, never to no wall at all");
  const c = focus04Rig({}, { load: { state: stamp, prev: null } });
  c.p.hydrateFocusNow(Date.UTC(2026, 7, 14, 18, 0));
  assert.deepEqual(c.p.getFocusLimits().limits, { vol: FOCUS_HARD_VOL, oi: FOCUS_HARD_OI }, "a pre-build blob carries no floors and hydrates to the backstop");
});

test("focus -04: the panel's scan is the ENGINE's eligible field, not a second opinion", () => {
  // One structural predicate (focusEligible) feeds both the expensive candidate assembly and the
  // cheap panel scan. If they could drift, every survivor count the panel prints would be a claim
  // about a different universe than the one the gate actually walks.
  const { p, OPEN } = focus04Rig(FOCUS04_FULL);
  const sc = p.getFocusLimits().scan;
  assert.equal(sc.length, 10, "the scan carries exactly the structurally eligible names");
  assert.ok(sc.every((r) => Array.isArray(r) && r.length === 4), "compact rows: [ticker, vol, oi, cluster]");
  assert.ok(sc[0][1] >= sc[sc.length - 1][1], "sorted by volume so the panel's histogram needs no second sort");
  const noOi = sc.find((r) => r[0] === "PLTR");
  assert.equal(noOi[2], null, "a missing OI read ships as null — the panel must be able to say 'no read', not '$0'");
  p.focusTickNow(OPEN + 60000);
  assert.equal(p.getFocus(OPEN + 60000).today.scanned, sc.length,
    "the stamp's scanned count and the panel's scan length are the same number, because they are the same predicate");
});

test("focus -04: manifest pins — the gate, the routes, the two-lock write, the panel and the roster", () => {
  const fs = require("fs"), path = require("path");
  const rd = (f) => fs.readFileSync(path.join(__dirname, "..", f), "utf8");
  const cmp = rd("src/compute.js"), pol = rd("src/poller.js"), srv = rd("server.js"),
    app = rd("public/app.js"), idx = rd("public/index.html"), css = rd("public/styles.css");
  // manifest: the write verb owns its own act key, path-wide (the GET returns the scan and is
  // exactly as admin-only as the write), so opening the focus TAB can never open the wall.
  assert.ok(cmp.includes('{ key: "focus.limits",  kind: "act", label: "Set FOCUS liquidity floors", def: "admin", routes: ["/api/focus/limits"] }'),
    "focus.limits manifest entry (admin, path-wide)");
  const { featureGateFor } = require("../src/compute");
  assert.equal(featureGateFor("POST", "/api/focus/limits", {}, false), "focus.limits", "a public caller is gated on the write");
  assert.equal(featureGateFor("GET", "/api/focus/limits", {}, false), "focus.limits", "…and on the read, which carries the scan");
  assert.equal(featureGateFor("GET", "/api/focus/limits", {}, true), null, "admin proceeds");
  // compute: the three pure pieces and the backstop live here, not in the poller
  for (const pin of ["const FOCUS_HARD_VOL = 200000", "function focusLimits(", "function focusFloorFail(",
    "function focusGate(", "module.exports.focusGate = focusGate;"])
    assert.ok(cmp.includes(pin), "compute pin: " + pin);
  // poller: one eligibility predicate, the gate at BOTH call sites, the frozen wall on the record
  assert.ok(!pol.includes("FOCUS_MIN_VOL"), "no second volume floor survives in the poller");
  assert.equal(pol.split("focusGate(cands, focusLim").length - 1, 2, "the gate runs at exactly two call sites — preview and stamp, one wall");
  assert.equal(pol.split("function focusEligible(").length - 1, 1, "exactly one structural predicate");
  for (const pin of ["limits: g.limits, scanned: g.scanned, cleared: g.pass.length, below: g.below, belowN: g.belowN",
    "function setFocusLimits(", "focusLim = focusLimits(data.limits);", "store.saveFocus({ state: focusState, prev: focusPrev, limits: focusLim })",
    "getFocusLimits:", "setFocusLimits,"])
    assert.ok(pol.includes(pin), "poller pin: " + pin);
  // the write must not touch the frozen record — the absence of a focusState mutation is the pin
  const setBody = pol.slice(pol.indexOf("function setFocusLimits("), pol.indexOf("function focusEligible("));
  assert.ok(!/focusState\s*=/.test(setBody), "setting floors never rewrites today's stamp");
  assert.ok(setBody.includes("focusPv = null;"), "…it drops the live preview pool so the prep list re-gates");
  // server: both verbs, admin re-checked in-handler on top of the manifest gate (two locks)
  assert.ok(srv.includes('fastify.get("/api/focus/limits"') && srv.includes('fastify.post("/api/focus/limits"'), "both limit routes");
  assert.equal(srv.split("poller.setFocusLimits(").length - 1, 1, "exactly one writer");
  const limBlock = srv.slice(srv.indexOf('fastify.get("/api/focus/limits"'), srv.indexOf('fastify.get("/api/whale"'));
  assert.equal(limBlock.split("isAdmin(req)").length - 1, 2, "both verbs re-check the admin cookie — manifest visibility and authz are separate axes");
  assert.ok(limBlock.includes('cache-control", "no-store"'), "the scan is never cached — calibrating against yesterday's volumes is the failure this prevents");
  // client: the panel, its hover contract, and the roster
  for (const pin of ["function renderAdmFloors(", "function admFlHist(", "function admFlProject(",
    "async function saveAdmFloors(", "loadAdmFloors();", "function focBelowHtml(", "FOC.showBelow"])
    assert.ok(app.includes(pin), "app pin: " + pin);
  assert.ok(idx.includes('id="admFloorsBox"'), "the panel has a mount point in the admin view");
  // EVERY bar carries a readout (the standing hover contract for charts) and the floor line is draggable
  assert.ok(/admfl-bar[^"]*"[^>]*data-tip=/.test(app), "every histogram bar carries a hover readout");
  assert.ok(app.includes("sv.addEventListener('mousedown'") && app.includes("sv.addEventListener('mousemove'"), "the floor line is draggable on the chart");
  // the panel reconciles with the SERVER's resolved floors, never with what was asked
  assert.ok(app.includes("_admFlV=d.limits.vol; _admFlO=d.limits.oi;"), "the save path adopts the server's clamped answer");
  // the roster reads the RECORD's own wall, never the live one
  assert.ok(app.includes("focBelowHtml(day,day.limits||d.limits)"), "the stamped table's roster reads the record's own floors");
  assert.ok(css.includes(".focbf") && css.includes(".admfl-hist") && css.includes(".admfl-bar"), "roster + panel styles present");
});

// ============================================================================================
// FOCUS -05 (build 2026.08.18-04): the opening hour on 1m, a capture lane the seats own, and a
// dash that states its own cause. The defect this replaces: four of six seats reached 10:37 with
// zero bars, and foldLiveMark turned the mark into hi = lo = last, so the board printed a flat
// line at the current price that was indistinguishable from a real first-hour measurement.
// ============================================================================================

test("focus -05: a seat with no bars produces NO record — the mark can widen a measurement, never be one", () => {
  const { firstHourStats, foldLiveMark } = require("../src/compute");
  const open = Date.UTC(2026, 7, 18, 13, 30);
  // THE REGRESSION, stated as an assertion. foldLiveMark(null, px) still synthesises a
  // single-point record — that behaviour is correct and load-bearing for a hour that HAS bars but
  // whose latest extreme is the live mark. What changed is that the forming builder no longer
  // feeds it a null: with zero bars there is nothing to widen and no record is published.
  const synth = foldLiveMark(null, 20.127);
  assert.deepEqual([synth.hi, synth.lo, synth.lastPx, synth.bars], [20.127, 20.127, 20.127, 0],
    "the fold's null path still fabricates a flat point — which is exactly why it must not be reached with zero bars");
  assert.equal(synth.vwap, null, "…and it cannot claim a VWAP, which is how the screenshot's dashed sVWAP sat beside numeric HI/LO");
  assert.equal(firstHourStats([], open, open + 3600e3, 1), null, "no bars in the window -> no stats, at any minBars");
  // A real one-bar hour is still a real read: the fix must not throw the honest single-bar case out.
  const one = firstHourStats([[open, 100, 101, 99, 100.5, 5000]], open, open + 3600e3, 1);
  assert.ok(one && one.bars === 1 && one.hi === 101, "one closed 1m bar is a measurement and stays one");
  const widened = foldLiveMark(one, 103);
  assert.equal(widened.hi, 103, "the mark widens the extreme");
  assert.equal(widened.vwap, one.vwap, "…and never touches VWAP — a mark carries no volume");
});

test("focus -05: the forming builder publishes coverage for every seat and a record for none that lack bars", () => {
  const { createPoller } = require("../src/poller");
  const base = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null };
  const OPEN = Date.UTC(2026, 7, 14, 13, 30), M = 60000;
  // Two seats: one the lane captured, one it did not. The stub serves 1m bars ONLY for BE.
  const bars = [];
  for (let i = 0; i < 12; i++) bars.push([OPEN + i * M, 100 + i * 0.1, 101 + i * 0.1, 99 + i * 0.1, 100.5 + i * 0.1, 1000]);
  let read5 = 0, read1 = 0;
  const store = { ...base, saveFocus: () => {}, loadFocus: () => null,
    candlesEnabled: () => true,
    readCandles: () => { read5++; return bars; },                      // the 5m archive: must NOT be consulted
    readCandles1m: (coin) => { read1++; return coin === "xyz:BE" ? bars : []; } };
  const p = createPoller({ dex: "xyz", store, log: () => {}, version: "test" });
  const spine = (px) => { const o = []; for (let i = 48; i >= 0; i--) o.push({ t: OPEN - i * 3600e3, o: px, h: px * 1.01, l: px * 0.99, c: px, v: 1e6 }); return o; };
  for (const [t, px] of [["BE", 218.97], ["KORU", 20.127], ["NVDA", 900], ["MU", 100], ["AMD", 150],
    ["LLY", 800], ["TSLA", 300], ["XOM", 110], ["JPM", 200], ["COIN", 250]])
    p.seedRowNow("xyz:" + t, { ticker: t, uni: "xyz", px, vol: 9e6, oi: 9e6, oiBase: 1000, hourlyRaw: spine(px) });
  p.focusTickNow(OPEN + 20 * M);
  const f = p.getFocus(OPEN + 20 * M);
  assert.ok(f.today, "the day stamps");
  assert.ok(read1 > 0, "the forming read consults the 1m archive");
  assert.equal(read5, 0, "…and never the 5m archive — one base for the hour this tab measures");
  const fm = f.forming;
  assert.ok(fm, "a forming edition publishes");
  assert.equal(fm.src, "1m", "the edition states its base resolution");
  if (f.today.rows.some((r) => r.ticker === "BE")) {
    assert.ok(fm.map.BE, "a seat with bars carries a forming record");
    assert.ok(fm.cov.BE && fm.cov.BE.bars === 12, "…and its bar count");
  }
  if (f.today.rows.some((r) => r.ticker === "KORU")) {
    assert.equal(fm.map.KORU, undefined, "a seat with NO bars publishes no forming record — not a flat point built from the mark");
    assert.ok(fm.cov.KORU && fm.cov.KORU.bars === 0, "…but it DOES publish coverage, so the board can say why rather than showing a blank");
    assert.ok(fm.cov.KORU.mins > 0, "…against the elapsed minutes, so 'zero of twenty' is readable");
  }
  assert.ok(fm.next > fm.at, "the edition carries its own next-republish time");
});

test("focus -05: the freeze reads 1m, records per-seat coverage, and stamps the resolution it measured at", () => {
  const { createPoller } = require("../src/poller");
  const base = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null };
  const OPEN = Date.UTC(2026, 7, 14, 13, 30), M = 60000;
  const bars = [];
  for (let i = 0; i < 60; i++) bars.push([OPEN + i * M, 100, 100 + (i === 30 ? 6 : 1), 100 - (i === 45 ? 4 : 1), 100.5, 1000]);
  let saved = null;
  const store = { ...base, saveFocus: (d) => { saved = d; }, loadFocus: () => null,
    candlesEnabled: () => true, readCandles: () => { throw new Error("the freeze must not read the 5m archive"); },
    readCandles1m: (coin) => (coin === "xyz:KORU" ? [] : bars) };
  const p = createPoller({ dex: "xyz", store, log: () => {}, version: "test" });
  const spine = (px) => { const o = []; for (let i = 48; i >= 0; i--) o.push({ t: OPEN - i * 3600e3, o: px, h: px * 1.01, l: px * 0.99, c: px, v: 1e6 }); return o; };
  for (const [t, px] of [["BE", 218.97], ["KORU", 20.127], ["NVDA", 900], ["MU", 100], ["AMD", 150],
    ["LLY", 800], ["TSLA", 300], ["XOM", 110], ["JPM", 200], ["COIN", 250]])
    p.seedRowNow("xyz:" + t, { ticker: t, uni: "xyz", px, vol: 9e6, oi: 9e6, oiBase: 1000, hourlyRaw: spine(px) });
  p.focusTickNow(OPEN + 5 * M);
  p.focusTickNow(OPEN + 61 * M);                       // past +1h: the freeze fires
  const rec = p.getFocus(OPEN + 61 * M).today;
  assert.ok(rec.filledAt, "the record froze");
  assert.equal(rec.h1src, "1m", "the record states the resolution its geometry was measured at");
  assert.equal(p.getFocus(OPEN + 61 * M).forming, null, "the frozen record replaces every forming read");
  for (const seat of rec.rows) {
    assert.ok(seat.h1cov, "every seat carries coverage, present or absent");
    if (seat.ticker === "KORU") {
      assert.equal(seat.h1, null, "a seat the lane never captured freezes as an honest null");
      assert.equal(seat.h1cov.bars, 0, "…with zero recorded, so the dash can name its cause months later");
    } else {
      assert.ok(seat.h1 && seat.h1.bars === 60, "a captured seat freezes 60 one-minute bars");
      assert.equal(seat.h1.hi, 106, "…with the true bar extreme, not a 5m approximation of it");
      assert.equal(seat.h1cov.bars, 60);
    }
  }
  assert.ok(saved && saved.state && saved.state.h1src === "1m", "the resolution persists with the record");
});

test("focus -05: the chart splices 1m over the same window and never counts a trade twice", () => {
  const { createPoller } = require("../src/poller");
  const base = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null };
  const OPEN = Date.UTC(2026, 7, 14, 13, 30), M = 60000, F = 5 * M;
  // The SAME hour in both archives — which is the whole hazard: these are the same trades.
  const b5 = [], b1 = [];
  for (let i = 0; i < 12; i++) b5.push([OPEN + i * F, 100, 102, 98, 101, 5000]);
  for (let i = 0; i < 60; i++) b1.push([OPEN + i * M, 100, 102, 98, 101, 1000]);
  const pre = [];
  for (let i = 12; i >= 1; i--) pre.push([OPEN - i * F, 99, 99.5, 98.5, 99, 4000]);
  const store = { ...base, saveFocus: () => {}, loadFocus: () => null, candlesEnabled: () => true,
    candleCoverage: () => ({ min: OPEN - 12 * F, max: OPEN + 12 * F, count: 24 }),
    readCandles: (c, lo, hi) => [...pre, ...b5].filter((k) => k[0] >= lo && k[0] <= hi),
    readCandles1m: (c, lo, hi) => b1.filter((k) => k[0] >= lo && k[0] <= hi) };
  const p = createPoller({ dex: "xyz", store, log: () => {}, version: "test" });
  const spine = (px) => { const o = []; for (let i = 48; i >= 0; i--) o.push({ t: OPEN - i * 3600e3, o: px, h: px * 1.01, l: px * 0.99, c: px, v: 1e6 }); return o; };
  for (const [t, px] of [["BE", 100], ["NVDA", 900], ["MU", 100], ["AMD", 150], ["LLY", 800],
    ["TSLA", 300], ["XOM", 110], ["JPM", 200], ["COIN", 250], ["PLTR", 60]])
    p.seedRowNow("xyz:" + t, { ticker: t, uni: "xyz", px, vol: 9e6, oi: 9e6, oiBase: 1000, hourlyRaw: spine(px) });
  p.focusTickNow(OPEN + 5 * M);
  const seat = p.getFocus(OPEN + 5 * M).today.rows[0].coin;
  const out = p.getCandles5m(seat, OPEN - 12 * F, OPEN + 12 * F, 6000);
  const inWin = out.candles.filter((k) => k[0] >= OPEN && k[0] < OPEN + 12 * F);
  assert.equal(inWin.length, 12, "the window still yields twelve 5m buckets — the 1m base is rolled UP, not shipped raw");
  // THE DOUBLE-COUNT GUARD. 5 x 1000 = 5000 per bucket, exactly the 5m bar's own volume. Summing
  // both archives would give 10000 and quietly double every volume (and skew every VWAP) in the
  // one window this tab measures most closely.
  assert.ok(inWin.every((k) => k[5] === 5000), "each spliced bucket carries the volume ONCE — overlapping 5m rows are dropped, never added");
  assert.equal(out.candles.filter((k) => k[0] < OPEN).length, 12, "pre-open bars still come from the 5m archive");
  const ts = out.candles.map((k) => k[0]);
  assert.deepEqual(ts, [...ts].sort((a, b) => a - b), "the spliced series stays ordered across the seam");
  assert.equal(new Set(ts).size, ts.length, "no timestamp appears twice — the seam is exact, not overlapping");
  // A coin that never held a seat has no 1m window and is untouched by any of this.
  const other = p.getCandles5m("xyz:NOTASEAT", OPEN - 12 * F, OPEN + 12 * F, 6000);
  assert.ok(other.candles.length > 0, "a non-seat still charts from the 5m archive alone");
});

test("focus -05: the seat lane is scoped to the seats and to the window, and idles the rest of the day", () => {
  const fs = require("fs"), path = require("path");
  const pol = fs.readFileSync(path.join(__dirname, "..", "src", "poller.js"), "utf8");
  // The lane must read the seats from focusState — one producer of "who is seated" — rather than
  // keeping its own list that a late boot stamp could leave stale.
  const w = pol.slice(pol.indexOf("function m1Seats("), pol.indexOf("const need5m ="));
  assert.ok(w.includes("const st = focusState;"), "the lane reads the live stamp, never a copy");
  assert.ok(w.includes("st.day !== etDayStr(now)"), "a stale day's seats are not captured");
  assert.ok(/now < st\.open - M1_PAD \|\| now > st\.open \+ HOUR \+ M1_PAD/.test(w), "the window is the stamped hour plus a pad at both edges");
  assert.ok(w.includes("await sleep(15000); continue;"), "outside the window the lane idles rather than spinning");
  assert.ok(w.includes('inflight.has("m1:"'), "per-coin inflight guard, like every other lane");
  assert.ok(/catch \(_\) \{ \/\* one seat's failure must not cost the other five their window \*\//.test(w),
    "one seat's failure cannot take the window from the rest — the starvation this build exists to fix");
  // The 1m bars must land in their OWN table: candles_5m is range-read as 5m by four other
  // consumers, and mixing off-grid timestamps into it would corrupt all of them silently.
  const sto = fs.readFileSync(path.join(__dirname, "..", "src", "store.js"), "utf8");
  assert.ok(sto.includes("CREATE TABLE IF NOT EXISTS candles_1m"), "1m bars have their own table");
  assert.ok(sto.includes("insertCandles1m(coin, rows)") && sto.includes("readCandles1m(coin, from, to)")
    && sto.includes("evictCandles1m(before)"), "the 1m sub-store carries insert, read and retention");
  assert.ok(!/insertCandles\(coin, rows\)[\s\S]{0,400}candles_1m/.test(sto), "the 5m writer never touches the 1m table");
  assert.ok(pol.includes("store.insertCandles1m(coin, closed)"), "the lane writes only closed bars");
  assert.ok(pol.includes("k[0] + 60000 <= now"), "…on a one-minute closed-bar guard");
});

test("focus -05: manifest pins — 1m base everywhere the hour is measured, 30s cadence, honest dash", () => {
  const fs = require("fs"), path = require("path");
  const rd = (f) => fs.readFileSync(path.join(__dirname, "..", f), "utf8");
  const pol = rd("src/poller.js"), app = rd("public/app.js"), css = rd("public/styles.css");
  // engine: both the forming read and the freeze read 1m; neither reads 5m for the hour
  assert.equal(pol.split("store.readCandles1m(p.coin").length - 1, 3, "forming, freeze and the close fill read the 1m archive — exactly three sites (-19-05)");
  assert.ok(!/readCandles\(p\.coin/.test(pol), "no first-hour path reads the 5m archive any more");
  assert.ok(pol.includes("const FOCUS_FORMING_MS = 25 * 1000"), "republish cadence sits inside the client's 30s poll");
  assert.ok(pol.includes("formingMs: FOCUS_FORMING_MS"), "…and ships on the payload so the two cannot drift");
  assert.ok(pol.includes('st.h1src = "1m";'), "the freeze stamps its resolution on the record");
  assert.ok(pol.includes("cov[p.ticker] = { bars: bars.length"), "forming publishes per-seat coverage");
  assert.ok(/r\.p\.h1cov = \{ bars: r\.n, mins, inWin:/.test(pol),
    "the frozen record carries coverage too — raw read AND the in-window count the geometry used");
  assert.ok(pol.includes("if (!f) continue;"), "no bars -> no forming record, so the fold is never handed a null");
  // splice: 1m authoritative, overlapping 5m dropped
  assert.ok(pol.includes("rows5.filter((k) => k[0] < win.from || k[0] > win.to).concat(rolled)"),
    "the overlapping 5m rows are DROPPED before the 1m rollup is concatenated — the double-count guard");
  assert.ok(pol.includes("bucketCandles(raw1, 5, 60000)"), "1m rolls up to the 5m grid server-side, so the client keeps one base");
  assert.ok(pol.includes("function m1Window("), "one resolver owns which span the 1m archive covers");
  // client: cadence follows the server, the dry cell states itself, no 1m timeframe is offered
  assert.ok(app.includes("function focArmPoll(") && app.includes("(FOC.data.formingMs||25000)"), "the poll follows the server's cadence");
  assert.ok(app.includes("function focDry(") && app.includes('focpend dry'), "a seat with no bars has its own state and its own reason");
  assert.ok(!/data-tf="1"/.test(app) && !/>1m</.test(app.slice(app.indexOf("function focChartOpen("), app.indexOf("function focChartOpen(") + 9000)),
    "the 1m timeframe is never offered in the chart selector — it is a base, not a view");
  assert.ok(css.includes(".foctbl td.focpend.dry"), "the dry state is visually distinct from 'still filling'");
});

test("whale who-holds (2026.08.18-05): reverse lookup matches by ticker/name/substring/cusip with disclosed basis, keeps option lines separate, surfaces exits, misses honestly", async () => {
  const { createPoller } = require("../src/poller");
  const store = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null,
    saveWhale: () => {}, loadWhale: () => null };
  const J = (o) => ({ ok: true, json: async () => o, text: async () => JSON.stringify(o) });
  const X = (t) => ({ ok: true, json: async () => { throw new Error("xml"); }, text: async () => t });
  const row = (nm, cu, v, sh, pc) => `<infoTable><nameOfIssuer>${nm}</nameOfIssuer><cusip>${cu}</cusip><value>${v}</value><shrsOrPrnAmt><sshPrnamt>${sh}</sshPrnamt><sshPrnamtType>SH</sshPrnamtType></shrsOrPrnAmt>${pc ? "<putCall>" + pc + "</putCall>" : ""}</infoTable>`;
  // Fund A: AAPL common (trimmed) + AAPL puts (new) + UNH; prior quarter had AAPL bigger + ULTA (exit).
  const A_Q2 = `<x>${row("APPLE INC", "037833100", 1000e6, 10e6)}${row("APPLE INC", "037833100", 200e6, 2e6, "Put")}${row("UNITEDHEALTH GROUP INC", "91324P102", 300e6, 1e6)}</x>`;
  const A_Q1 = `<x>${row("APPLE INC", "037833100", 1500e6, 15e6)}${row("ULTA BEAUTY INC", "90384S303", 90e6, 2e5)}</x>`;
  // Fund B: AAPL common (added).
  const B_Q2 = `<x>${row("APPLE INC", "037833100", 400e6, 4e6)}${row("NVIDIA CORPORATION", "67066G104", 250e6, 5e5)}</x>`;
  const B_Q1 = `<x>${row("APPLE INC", "037833100", 300e6, 3e6)}${row("NVIDIA CORPORATION", "67066G104", 200e6, 4e5)}</x>`;
  const sub = (accQ2, accQ1) => J({ name: "X", filings: { recent: {
    form: ["13F-HR", "13F-HR"], accessionNumber: [accQ2, accQ1],
    filingDate: ["2026-08-14", "2026-05-15"], reportDate: ["2026-06-30", "2026-03-31"] } } });
  const idx = J({ directory: { item: [{ name: "primary_doc.xml", size: 9 }, { name: "infotable.xml", size: 999 }] } });
  const extFetch = async (url) => {
    if (url.includes("company_tickers.json")) return J({ 0: { cik_str: 1, ticker: "AAPL", title: "Apple Inc." }, 1: { cik_str: 2, ticker: "NVDA", title: "NVIDIA Corporation" } });
    if (url.includes("company_tickers_mf")) return J({ fields: ["cik"], data: [] });
    if (url.includes("submissions/CIK0000000101")) return sub("0101-26-000002", "0101-26-000001");
    if (url.includes("submissions/CIK0000000102")) return sub("0102-26-000002", "0102-26-000001");
    if (url.includes("/010126000002/infotable.xml")) return X(A_Q2);
    if (url.includes("/010126000001/infotable.xml")) return X(A_Q1);
    if (url.includes("/010226000002/infotable.xml")) return X(B_Q2);
    if (url.includes("/010226000001/infotable.xml")) return X(B_Q1);
    if (url.includes("/index.json")) return idx;
    return { ok: false, status: 404, error: "404" };
  };
  const p = createPoller({ dex: "xyz", store, log: () => {}, version: "test", crypto: false, extFetch });
  p.hydrateWhaleNow();
  p.whaleAdd(101, "Alpha Capital LP"); p.whaleAdd(102, "Beta Partners LLC");
  await p.whalePull("ALPHA"); await p.whalePull("BETA");
  // Ticker lane: AAPL resolves via the company map; basis disclosed; both funds found, sorted by size.
  let r = await p.getWhaleHolds("AAPL");
  assert.ok(r.ok, r.error || "");
  assert.ok(/ticker "AAPL"/.test(r.basis), "basis names the lane that matched");
  assert.equal(r.held, 2); assert.equal(r.watchN, 2);
  assert.equal(r.funds[0].key, "ALPHA", "sorted by combined position size");
  const alpha = r.funds[0];
  assert.equal(alpha.lines.length, 2, "common and puts are SEPARATE lines, never merged");
  const common = alpha.lines.find((l) => !l.put), puts = alpha.lines.find((l) => l.put === "put");
  assert.equal(common.d.cls, "trim"); assert.equal(common.d.dSh, -5e6, "share delta off the real delta engine");
  assert.equal(puts.d.cls, "new", "the puts line opened this quarter");
  assert.equal(common.rank, 1, "rank inside the fund's book");
  assert.equal(r.combined, 1000e6 + 200e6 + 400e6, "combined sums every matched line");
  assert.equal(r.adding, 1, "BETA's common grew — and ALPHA's NEW PUTS line must NOT count as adding (options never drive the directional strip)");
  assert.equal(r.cutting, 1, "ALPHA's common trim");
  // Exit lane: ULTA held in Q1, absent in Q2 — surfaced as an exited fund row, counted as cutting.
  r = await p.getWhaleHolds("ULTA");
  assert.ok(r.ok);
  assert.equal(r.held, 0); assert.equal(r.funds.length, 1);
  assert.equal(r.funds[0].key, "ALPHA"); assert.equal(r.funds[0].exited[0].prevVal, 90e6);
  assert.ok(r.notHeld.includes("BETA"), "the fund that never touched it is listed not-held");
  // Substring lane (>=3 chars) + name lane.
  r = await p.getWhaleHolds("unitedhealth");
  assert.ok(r.ok && r.held === 1 && r.funds[0].key === "ALPHA");
  // CUSIP lane, exact 9 chars.
  r = await p.getWhaleHolds("67066G104");
  assert.ok(r.ok && /CUSIP/.test(r.basis) && r.funds[0].key === "BETA");
  // Two-char query only matches as a ticker — no substring fishing.
  r = await p.getWhaleHolds("UN");
  assert.ok(!r.ok && r.miss === 1, "short fragments don't substring-match");
  assert.ok(/searched 2 book/.test(r.error) && /Not held \u2260 not owned/.test(r.error), "the miss states scan scope and the 13F blindness caveat");
  // Wiring pins.
  const fs = require("fs"), path = require("path");
  const sv = fs.readFileSync(path.join(__dirname, "..", "server.js"), "utf8");
  assert.ok(sv.includes("qq.holds != null") && sv.includes("getWhaleHolds"), "route branch wired");
  const app = fs.readFileSync(path.join(__dirname, "..", "public", "app.js"), "utf8");
  assert.ok(app.includes("whl-whoq") && app.includes("whlWho(") && app.includes("sub==='who'||sub==='holds'"), "panel + terminal verbs present");
  assert.ok(app.includes("data-whlopen2"), "a holds row deep-links to the fund's full book");
});

test("whale who-holds -07: a spelling collision is two issuers, never one merged result — per-issuer basis/name/ticker/totals, exclusive direction counts, common vs option notional split", async () => {
  const { createPoller } = require("../src/poller");
  const C = require("../src/compute");
  const store = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null,
    saveWhale: () => {}, loadWhale: () => null };
  const J = (o) => ({ ok: true, json: async () => o, text: async () => JSON.stringify(o) });
  const X = (t) => ({ ok: true, json: async () => { throw new Error("xml"); }, text: async () => t });
  const row = (nm, cu, v, sh, pc, cls) => `<infoTable><nameOfIssuer>${nm}</nameOfIssuer>${cls ? "<titleOfClass>" + cls + "</titleOfClass>" : ""}<cusip>${cu}</cusip><value>${v}</value><shrsOrPrnAmt><sshPrnamt>${sh}</sshPrnamt><sshPrnamtType>SH</sshPrnamtType></shrsOrPrnAmt>${pc ? "<putCall>" + pc + "</putCall>" : ""}</infoTable>`;
  // The shipped -06 failure, reproduced exactly: the query "AMD" resolves to ADVANCED MICRO
  // DEVICES by ticker AND appears inside "AMDOCS LTD" by substring. Two issuers, two CUSIP
  // prefixes (007903 / G02602). ALPHA holds both.
  // ALPHA also holds AMD across TWO common lots that move in OPPOSITE directions (COM up, SHS
  // down) — the -06 double-count fixture — plus an options line that must never vote.
  const A_Q2 = `<x>${row("ADVANCED MICRO DEVICES INC", "007903107", 900e6, 9e6, null, "COM")}`
    + `${row("AMD INC", "007903206", 20e6, 2e5, null, "SHS")}`
    + `${row("ADVANCED MICRO DEVICES INC", "007903107", 500e6, 5e6, "Put", "COM")}`
    + `${row("AMDOCS LTD", "G02602103", 30e6, 3e5, null, "COM")}</x>`;
  const A_Q1 = `<x>${row("ADVANCED MICRO DEVICES INC", "007903107", 600e6, 6e6, null, "COM")}`
    + `${row("AMD INC", "007903206", 40e6, 4e5, null, "SHS")}`
    + `${row("AMDOCS LTD", "G02602103", 20e6, 2e5, null, "COM")}</x>`;
  // BETA holds ONLY the collision name — it must be not-held on AMD and a holder on AMDOCS.
  const B_Q2 = `<x>${row("AMDOCS LTD", "G02602103", 50e6, 5e5, null, "COM")}</x>`;
  const B_Q1 = `<x>${row("AMDOCS LTD", "G02602103", 80e6, 8e5, null, "COM")}</x>`;
  const sub = (a2, a1) => J({ name: "X", filings: { recent: {
    form: ["13F-HR", "13F-HR"], accessionNumber: [a2, a1],
    filingDate: ["2026-08-14", "2026-05-15"], reportDate: ["2026-06-30", "2026-03-31"] } } });
  const idx = J({ directory: { item: [{ name: "primary_doc.xml", size: 9 }, { name: "infotable.xml", size: 999 }] } });
  const extFetch = async (url) => {
    if (url.includes("company_tickers.json")) return J({ 0: { cik_str: 1, ticker: "AMD", title: "Advanced Micro Devices, Inc." },
      1: { cik_str: 2, ticker: "DOX", title: "Amdocs Limited" } });
    if (url.includes("company_tickers_mf")) return J({ fields: ["cik"], data: [] });
    if (url.includes("submissions/CIK0000000201")) return sub("0201-26-000002", "0201-26-000001");
    if (url.includes("submissions/CIK0000000202")) return sub("0202-26-000002", "0202-26-000001");
    if (url.includes("/020126000002/infotable.xml")) return X(A_Q2);
    if (url.includes("/020126000001/infotable.xml")) return X(A_Q1);
    if (url.includes("/020226000002/infotable.xml")) return X(B_Q2);
    if (url.includes("/020226000001/infotable.xml")) return X(B_Q1);
    if (url.includes("/index.json")) return idx;
    return { ok: false, status: 404, error: "404" };
  };
  const p = createPoller({ dex: "xyz", store, log: () => {}, version: "test", crypto: false, extFetch });
  p.hydrateWhaleNow();
  p.whaleAdd(201, "Alpha Capital LP"); p.whaleAdd(202, "Beta Partners LLC");
  await p.whalePull("ALPHA"); await p.whalePull("BETA");

  // --- the issuer key is identity, not spelling -------------------------------------------------
  assert.equal(C.whaleIssuerKey("007903107", "ADVANCED MICRO DEVICES INC"), "C:007903");
  assert.equal(C.whaleIssuerKey("G02602103", "AMDOCS LTD"), "C:G02602");
  assert.notEqual(C.whaleIssuerKey("007903107", "X"), C.whaleIssuerKey("G02602103", "X"),
    "two issuers whose names collide must never share a key");
  assert.equal(C.whaleIssuerKey("BAD", "AMDOCS LTD"), "N:AMDOCS", "no usable cusip falls back to the normalized name");

  const r = await p.getWhaleHolds("AMD");
  assert.ok(r.ok, r.error || "");
  assert.equal(r.issuers.length, 2, "one query, two issuers — the collision is SPLIT, not unioned");

  // --- primary: strongest lane first, with its own name and ticker chip -------------------------
  const amd = r.issuers[0];
  assert.equal(amd.key, "C:007903", "the ticker lane outranks the substring lane");
  // ALPHA files the same issuer under two spellings ("ADVANCED MICRO DEVICES INC" on the COM and
  // puts lines, "AMD INC" on the second share class). The display name is the spelling the most
  // filers used, longest on a tie — NOT the shortest, which is the -06 rule that let a 10-char
  // coincidence title a panel about a 26-char company.
  assert.equal(amd.name, "ADVANCED MICRO DEVICES INC",
    "display name is the modal filed spelling for THIS issuer, not the shortest one in the bucket");
  assert.ok(amd.funds[0].lines.length === 3, "all three lines are in this issuer despite the spelling split");
  assert.ok(/ticker "AMD"/.test(amd.basisLabel), "basis is disclosed per issuer");
  assert.equal(amd.tk, "AMD");
  assert.equal(r.name, amd.name, "top-level mirrors the primary issuer for existing callers");
  assert.equal(r.basis, amd.basisLabel);

  // --- secondary: its own weaker basis, and NO borrowed ticker chip ------------------------------
  const dox = r.issuers[1];
  assert.equal(dox.key, "C:G02602");
  assert.equal(dox.name, "AMDOCS LTD");
  assert.ok(/substring/.test(dox.basisLabel), "the weak lane is named as the weak lane");
  assert.equal(dox.tk, null,
    "the AMD ticker chip belongs to the issuer the company map resolved — -06 stamped it on every issuer in the result");

  // --- totals are per-issuer and split by instrument ---------------------------------------------
  assert.equal(amd.common, 900e6 + 20e6, "common equity only");
  assert.equal(amd.optNotional, 500e6, "option underlying notional stated separately, never summed in");
  assert.equal(amd.combined, 920e6 + 500e6);
  assert.equal(dox.common, 30e6 + 50e6, "AMDOCS totals contain no AMD value whatsoever");
  assert.ok(dox.combined < amd.combined && dox.combined === 80e6, "-06 reported one combined figure spanning both companies");

  // --- holders and not-held are per-issuer ------------------------------------------------------
  assert.equal(amd.held, 1); assert.deepEqual(amd.notHeld, ["BETA"]);
  assert.equal(dox.held, 2); assert.deepEqual(dox.notHeld, []);

  // --- direction is exclusive: one fund, one vote ------------------------------------------------
  // ALPHA's AMD lots disagree (COM +3M sh, SHS -200k sh). -06 answered both `.some()` questions
  // and incremented adding AND cutting off the same fund.
  const alpha = amd.funds.find((f) => f.key === "ALPHA");
  assert.equal(alpha.lines.length, 3,
    "two share classes (007903107 COM, 007903206 SHS) plus the puts line — DIFFERENT cusips, SAME issuer, so the 6-char prefix is what folds them together");
  assert.equal(alpha.mixed, 1, "the row DISCLOSES that its legs disagree");
  assert.equal(alpha.dir, "add", "net across common lines decides; the puts line does not vote");
  assert.equal(amd.adding + amd.cutting + amd.flat, amd.held,
    "counts can never exceed the holder count — the shipped panel printed 3 adding + 2 cutting against 4 hold");
  assert.equal(amd.adding, 1); assert.equal(amd.cutting, 0);
  assert.equal(alpha.lines.length, 3, "COM, SHS and the puts line stay separate");
  assert.ok(alpha.lines.some((l) => l.put === "put") && alpha.lines.some((l) => l.cls && /SHS/.test(l.cls)),
    "the lot class rides every line so one chip component can render them all");
  // BETA cut AMDOCS; ALPHA grew it. Same denominator rule on the other issuer.
  assert.equal(dox.adding, 1); assert.equal(dox.cutting, 1);
  assert.equal(dox.adding + dox.cutting + dox.flat, dox.held);

  // --- an options-only holder is not a directional holder ----------------------------------------
  const optOnly = require("../src/poller");
  void optOnly;
  const r2 = await p.getWhaleHolds("007903107");
  assert.ok(r2.ok && /CUSIP/.test(r2.basis) && r2.issuers.length === 1,
    "an exact CUSIP resolves to exactly one issuer — no substring fishing alongside it");

  // --- client + wiring pins ----------------------------------------------------------------------
  const fs = require("fs"), path = require("path");
  const app = fs.readFileSync(path.join(__dirname, "..", "public", "app.js"), "utf8");
  assert.ok(app.includes("r.issuers") && app.includes("data-whoalt"), "the panel reads the issuer list and can expand a weaker match");
  assert.ok(app.includes("function whoLot(") && !app.includes("whl-clstag\">"),
    "one lot-class chip component; the -06 two-widget split is gone");
  assert.ok(/&lt;0\.1%/.test(app), "sub-0.05% renders as <0.1%, never a fabricated 0.0%");
  assert.ok(app.includes("whlSgnSh(d.dSh)} sh"), "the share unit is printed on the delta column");
  assert.ok(app.includes("optNotional"), "common and option notional are shown as two figures");
  const css = fs.readFileSync(path.join(__dirname, "..", "public", "styles.css"), "utf8");
  assert.ok(css.includes(".whl-wotbl{table-layout:fixed") && css.includes("col.wo-c1"),
    "columns are pinned — -06 let the FUND column absorb every pixel of slack");
  assert.ok(css.includes(".wo-fund>td{border-top"), "fund groups are visually separated");
});

test("whale season roster (2026.08.18-06): the producer exists — build writes agg.roster, payload serves cells, roster-less stored builds heal at hydrate without claiming amendment", async () => {
  const { createPoller } = require("../src/poller");
  const J = (o) => ({ ok: true, json: async () => o, text: async () => JSON.stringify(o) });
  const X = (t) => ({ ok: true, json: async () => { throw new Error("xml"); }, text: async () => t });
  const row = (nm, cu, v, sh, cls) => `<infoTable><nameOfIssuer>${nm}</nameOfIssuer>${cls ? "<titleOfClass>" + cls + "</titleOfClass>" : ""}<cusip>${cu}</cusip><value>${v}</value><shrsOrPrnAmt><sshPrnamt>${sh}</sshPrnamt><sshPrnamtType>SH</sshPrnamtType></shrsOrPrnAmt></infoTable>`;
  // Both funds hold BOTH Alphabet share classes — the duplicate-name case — plus a mover.
  const bookOf = (v) => `<x>${row("ALPHABET INC", "02079K305", v, 1e6, "CAP STK CL A")}${row("ALPHABET INC", "02079K107", v * 0.8, 8e5, "CAP STK CL C")}${row("MICRON TECHNOLOGY INC", "595112103", v * 0.5, 4e5)}</x>`;
  const sub = (pfx) => J({ name: "X", filings: { recent: {
    form: ["13F-HR", "13F-HR"], accessionNumber: [pfx + "-26-000002", pfx + "-26-000001"],
    filingDate: ["2026-08-14", "2026-05-15"], reportDate: ["2026-06-30", "2026-03-31"] } } });
  const idx = J({ directory: { item: [{ name: "primary_doc.xml", size: 9 }, { name: "infotable.xml", size: 999 }] } });
  const mkFetch = () => async (url) => {
    if (url.includes("company_tickers")) return J({});
    if (url.includes("submissions/CIK0000000201")) return sub("0201");
    if (url.includes("submissions/CIK0000000202")) return sub("0202");
    if (url.includes("infotable.xml")) return X(url.includes("/020126") ? bookOf(url.endsWith("2/infotable.xml") ? 1000e6 : 900e6) : bookOf(url.endsWith("2/infotable.xml") ? 600e6 : 500e6));
    if (url.includes("/index.json")) return idx;
    return { ok: false, status: 404, error: "404" };
  };
  const mkStore = (loaded, sink) => ({ loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null,
    saveWhale: (d) => { if (sink) sink.d = d; }, loadWhale: () => loaded });
  // Leg 1: a fresh build writes the roster — covered funds, watchlist order, key+cik.
  const sink = {};
  const p = createPoller({ dex: "xyz", store: mkStore(null, sink), log: () => {}, version: "test", crypto: false, extFetch: mkFetch() });
  p.hydrateWhaleNow();
  p.whaleAdd(201, "Gamma Capital LP"); p.whaleAdd(202, "Delta Advisors LLC");
  await p.whalePull("GAMMA"); await p.whalePull("DELTA");
  p.whaleSeasonNow(Date.UTC(2026, 7, 16, 12));   // injected grace clock — the real clock sits past Q2's grace, where the window builder has already rolled to Q3
  const s = await p.getWhaleSeasonQ("Q2 2026");
  assert.ok(s.ok, s.error || "");
  assert.deepEqual(s.agg.roster.map((r) => r.key), ["GAMMA", "DELTA"], "roster: covered funds, watch order");
  assert.ok(s.agg.roster.every((r) => Number.isFinite(+r.cik) && !r.dropped), "cik identity present, nobody falsely dropped");
  const alph = s.agg.crowd.filter((r) => r.name === "ALPHABET INC");
  assert.equal(alph.length, 2, "two share classes stay two crowd rows");
  assert.ok(alph.every((r) => r.cls) && alph[0].cls !== alph[1].cls, "each carries its own titleOfClass for on-screen disambiguation");
  assert.ok(alph.every((r) => r.state.GAMMA && r.state.DELTA), "cells have per-fund states for every roster fund");
  // Leg 2: a stored -18-01..-05 blob (accs present, agg.roster ABSENT) heals at hydrate alone —
  // no tick, no pull — and the heal does not claim an amendment.
  const stored = sink.d;
  assert.ok(stored && stored.seasons["Q2 2026"], "fixture: leg-1 state persisted");
  delete stored.seasons["Q2 2026"].agg.roster;                       // exactly what -18-01..-05 wrote
  stored.seasons["Q2 2026"].amended = 0;
  const p2 = createPoller({ dex: "xyz", store: mkStore(stored, null), log: () => {}, version: "test", crypto: false,
    extFetch: async () => ({ ok: false, status: 404, error: "404" }) });
  p2.hydrateWhaleNow();
  const s2 = await p2.getWhaleSeasonQ("Q2 2026");
  assert.ok(s2.ok && s2.agg.roster.length === 2, "roster-less stored season healed at hydrate, zero fetches");
  assert.equal(s2.amended, false, "a shape heal is not an amendment — nothing at EDGAR moved");
  // Wiring pins for the client half.
  const fs = require("fs"), path = require("path");
  const app = fs.readFileSync(path.join(__dirname, "..", "public", "app.js"), "utf8");
  assert.ok(app.indexOf("whl-who") < app.indexOf("d.watch.length?") && app.indexOf("whl-who") > app.indexOf("whl-head"), "-06: the search panel sits under the tab header, ABOVE the watchlist table — a search nobody finds is a search that doesn't exist");
  assert.ok(app.includes("whl-clstag"), "duplicate display names get their share-class tag");
  assert.ok(app.includes("grid cells pending one season rebuild"), "defensive note if an unhealed payload ever serves");
  const css = fs.readFileSync(path.join(__dirname, "..", "public", "styles.css"), "utf8");
  assert.ok(css.includes(".whl-who{border:1px solid"), "the panel is boxed, not a bare label");
});

test("whale season heal v2 (2026.08.19-01): aggregate and header fields are ONE computation — v1-healed mismatches self-repair, counts agree everywhere", async () => {
  const { createPoller } = require("../src/poller");
  const J = (o) => ({ ok: true, json: async () => o, text: async () => JSON.stringify(o) });
  const X = (t) => ({ ok: true, json: async () => { throw new Error("xml"); }, text: async () => t });
  const row = (nm, cu, v, sh) => `<infoTable><nameOfIssuer>${nm}</nameOfIssuer><cusip>${cu}</cusip><value>${v}</value><shrsOrPrnAmt><sshPrnamt>${sh}</sshPrnamt><sshPrnamtType>SH</sshPrnamtType></shrsOrPrnAmt></infoTable>`;
  const book = `<x>${row("APPLE INC", "037833100", 500e6, 5e6)}${row("MICRON TECHNOLOGY INC", "595112103", 300e6, 2e6)}</x>`;
  const sub = (pfx) => J({ name: "X", filings: { recent: {
    form: ["13F-HR", "13F-HR"], accessionNumber: [pfx + "-26-000002", pfx + "-26-000001"],
    filingDate: ["2026-08-14", "2026-05-15"], reportDate: ["2026-06-30", "2026-03-31"] } } });
  const idx = J({ directory: { item: [{ name: "primary_doc.xml", size: 9 }, { name: "infotable.xml", size: 999 }] } });
  const extFetch = async (url) => {
    if (url.includes("company_tickers")) return J({});
    if (url.includes("submissions/CIK0000000301")) return sub("0301");
    if (url.includes("submissions/CIK0000000302")) return sub("0302");
    if (url.includes("infotable.xml")) return X(book);
    if (url.includes("/index.json")) return idx;
    return { ok: false, status: 404, error: "404" };
  };
  const sink = {};
  const mkStore = (loaded) => ({ loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null,
    saveWhale: (d) => { sink.d = d; }, loadWhale: () => loaded });
  // Assemble real state: 2 funds with Q2 books, season built in-window.
  const p = createPoller({ dex: "xyz", store: mkStore(null), log: () => {}, version: "test", crypto: false, extFetch });
  p.hydrateWhaleNow();
  p.whaleAdd(301, "Epsilon Capital LP"); p.whaleAdd(302, "Zeta Partners LLC");
  await p.whalePull("EPSILON"); await p.whalePull("ZETA");
  p.whaleSeasonNow(Date.UTC(2026, 7, 16, 12));
  // Forge the exact production wreck the screenshot showed: a v1-healed blob whose agg says 2
  // funds while the header fields still describe a dead 8-fund build, PLUS a watch entry with no
  // book (the "missing" fund), PLUS amended=1 narrating an old amendment over it all.
  const stored = sink.d;
  const sn = stored.seasons["Q2 2026"];
  sn.healed = 1; delete sn.healv;
  sn.filedN = 7; sn.watchN = 8; sn.missing = ["PERSHING"]; sn.amended = 1;
  stored.watch.push({ key: "NOBOOK", name: "No Book Yet LP", cik: 999, notify: 1, addedAt: 1 });
  const p2 = createPoller({ dex: "xyz", store: mkStore(stored), log: () => {}, version: "test", crypto: false,
    extFetch: async () => ({ ok: false, status: 404, error: "404" }) });
  p2.hydrateWhaleNow();   // heal v2 fires here — no fetches, pure math
  const s = await p2.getWhaleSeasonQ("Q2 2026");
  assert.ok(s.ok, s.error || "");
  assert.equal(s.agg.nFunds, 2, "aggregate covers the 2 funds with stored books");
  assert.equal(s.filedN, 2, "header filedN describes the SAME computation as the lanes");
  assert.equal(s.watchN, 3, "watchN is today's watchlist, not a dead build's");
  assert.deepEqual(s.missing, ["NOBOOK"], "missing = today's watched funds without a book for the quarter — not a ghost from the old build");
  assert.equal(s.agg.roster.length, 2, "grid roster matches too — one story on the whole panel");
  assert.equal(s.healed, 1, "payload says it was healed; the client renders that instead of the amendment text");
  // Idempotence: a second boot re-runs nothing (healv=2 sticks) and the state is stable.
  const stored2 = sink.d;
  const p3 = createPoller({ dex: "xyz", store: mkStore(stored2), log: () => {}, version: "test", crypto: false,
    extFetch: async () => ({ ok: false, status: 404, error: "404" }) });
  p3.hydrateWhaleNow();
  const s3 = await p3.getWhaleSeasonQ("Q2 2026");
  assert.equal(s3.filedN, 2); assert.equal(s3.watchN, 3);
  const app = require("fs").readFileSync(require("path").join(__dirname, "..", "public", "app.js"), "utf8");
  assert.ok(app.includes("rebuilt from stored books"), "healed builds say what they are in both headers — not 'rebuilt after amendment'");
});

test("whale traded-basis lanes (2026.08.19-02): mark drift is priced out — share sellers cannot top MOST BOUGHT, lanes agree with crowding by construction", () => {
  const C = require("../src/compute");
  const P = (cu, nm, v, sh) => ({ cusip: cu, put: null, name: nm, cls: null, value: v, shares: sh, pct: null });
  // The screenshot scenario: MU's price doubles across the quarter. Two funds TRIM shares — their
  // dVal is POSITIVE (marks swamp the selling) — one small fund adds. Old dollar-net called this
  // +$40M "MOST BOUGHT" while the crowding grid said 2 cutting. One panel, two answers.
  const A = { key: "A", cur: { total: 1, n: 1, positions: [P("595112103", "MICRON TECHNOLOGY INC", 180e6, 1e6)] },
              prev: { total: 1, n: 1, positions: [P("595112103", "MICRON TECHNOLOGY INC", 150e6, 1.5e6)] } };
  const B = { key: "B", cur: { total: 1, n: 1, positions: [P("595112103", "MICRON TECHNOLOGY INC", 90e6, 0.5e6)] },
              prev: { total: 1, n: 1, positions: [P("595112103", "MICRON TECHNOLOGY INC", 80e6, 0.8e6)] } };
  const D = { key: "D", cur: { total: 1, n: 1, positions: [P("595112103", "MICRON TECHNOLOGY INC", 36e6, 0.2e6)] },
              prev: { total: 1, n: 1, positions: [P("595112103", "MICRON TECHNOLOGY INC", 18e6, 0.18e6)] } };
  const s = C.whaleSeason([A, B, D]);
  assert.equal(s.bought.length, 0, "a rallying stock everyone trimmed does NOT appear in MOST BOUGHT");
  assert.equal(s.sold.length, 1, "it lands in MOST SOLD — where the share counts say it belongs");
  const mu = s.sold[0];
  // Traded flow: (-0.5M x $180) + (-0.3M x $180) + (+0.02M x $180) = -140.4M, at each filing's own implied Q-end price.
  assert.ok(Math.abs(mu.net - (-140.4e6)) < 1e3, "net is TRADED dollars at implied quarter-end prices, got " + mu.net);
  assert.ok(mu.legs.every((l) => l.dTr != null), "every SH leg carries its traded estimate");
  assert.equal(mu.estN, 0, "no value-only legs here — nothing rides the polluted layer");
  // Crowding and the lane now read the same layer.
  const cr = s.crowd.find((r) => r.cusip === "595112103");
  assert.ok(cr && cr.cutting === 2 && cr.adding === 1, "crowding: 2 cutting, 1 adding — and the lane AGREES");
  // whaleDelta flows: the modal strip's TRIMMED box must be negative for A despite dVal +30M.
  const dd = C.whaleDelta(A.cur, A.prev);
  assert.equal(dd.rows[0].d.cls, "trim");
  assert.ok(dd.rows[0].d.dVal > 0, "fixture sanity: the polluted layer really does read positive");
  assert.ok(Math.abs(dd.rows[0].d.dTr - (-90e6)) < 1e3, "dTr prices the share change alone");
  assert.ok(Math.abs(dd.flows.trimmed - (-90e6)) < 1e3, "the strip's flow is traded dollars, not mark drift");
  // Fallback: an options leg (no comparable shares) still rides dVal, counted and disclosed.
  const O = (v) => ({ cusip: "595112103", put: "call", name: "MICRON TECHNOLOGY INC", cls: null, value: v, shares: null, pct: null });
  const E = { key: "E", cur: { total: 1, n: 1, positions: [O(50e6)] }, prev: { total: 1, n: 1, positions: [O(20e6)] } };
  const s2 = C.whaleSeason([E]);
  const call = (s2.bought.find((r) => r.put === "call")) || null;
  assert.ok(call && call.estN === 1, "value-only leg counted in estN — the row can say which layer it rides");
  // Migration: a stored season whose agg predates the traded basis (no aggV) rebuilds at hydrate
  // even with a perfect roster — new labels must never sit over old-math numbers.
  {
    const { createPoller } = require("../src/poller");
    const stored = { ts: 1,
      watch: [{ key: "A", name: "A LP", cik: 401, notify: 1, addedAt: 1 }],
      filings: { "401": { "Q2 2026": { acc: "x", form: "13F-HR", filedAt: 1, period: "2026-06-30", url: null, scaleChecked: 1,
        book: { total: 180e6, n: 1, nRaw: 1, positions: [{ cusip: "595112103", put: null, name: "MICRON TECHNOLOGY INC", cls: null, value: 180e6, shares: 1e6, pct: 100 }] } },
        "Q1 2026": { acc: "y", form: "13F-HR", filedAt: 1, period: "2026-03-31", url: null, scaleChecked: 1,
        book: { total: 150e6, n: 1, nRaw: 1, positions: [{ cusip: "595112103", put: null, name: "MICRON TECHNOLOGY INC", cls: null, value: 150e6, shares: 1.5e6, pct: 100 }] } } } },
      unseen: {}, seasons: { "Q2 2026": { q: "Q2 2026", at: 1, accs: { 401: "x:y" }, rosterSig: "401",
        filedN: 1, watchN: 1, missing: [], amended: 0,
        agg: { bought: [{ cusip: "595112103", put: null, name: "MICRON TECHNOLOGY INC", net: 30e6, legs: [{ key: "A", dVal: 30e6, dSh: -0.5e6 }], domPct: 100, held: 1, adding: 0, cutting: 1, opened: [], exited: [], state: { A: "trim" } }],
          sold: [], opens: [], exits: [], crowd: [], nFunds: 1, roster: [{ key: "A", cik: 401 }] } } } };   // old-math agg: trim shows as BOUGHT, no aggV
    const st = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null, saveLedger: () => {}, insert: () => {},
      saveRegime: () => {}, saveNews: () => {}, loadNews: () => null, saveWhale: () => {}, loadWhale: () => stored };
    const p4 = createPoller({ dex: "xyz", store: st, log: () => {}, version: "test", crypto: false,
      extFetch: async () => ({ ok: false, status: 404, error: "404" }) });
    p4.hydrateWhaleNow();
    return (async () => {
      const sh = await p4.getWhaleSeasonQ("Q2 2026");
      assert.ok(sh.ok, sh.error || "");
      assert.equal(sh.agg.bought.length, 0, "the old-math agg (trim shown as bought) was rebuilt at hydrate under the traded basis");
      assert.ok(sh.agg.sold.length === 1 && Math.abs(sh.agg.sold[0].net - (-90e6)) < 1e3, "and the rebuilt lane prices the share change: -0.5M sh x $180");
    })().then(() => {
  // Client pins: labels name the basis; tag collisions fall to cusip.
  const fs = require("fs"), path = require("path");
  const app = fs.readFileSync(path.join(__dirname, "..", "public", "app.js"), "utf8");
  assert.ok(app.includes("MOST BOUGHT \\u00b7 net traded $ (est)") && app.includes("MOST SOLD \\u00b7 net traded $ (est)"), "lane labels state the traded basis");
  assert.ok(app.includes("no comparable share counts"), "value-only legs disclosed per row");
  assert.ok(app.includes("tagCount"), "duplicate-name tags that collide (Equity/Equity) fall back to the cusip head");
    });
  }
});

test("whale season sync (2026.08.19-03): closed-quarter builds follow the live watchlist — no ghost 'missing', no denominator drift, late HR/As rebuild, all-dropped stays as labeled history", async () => {
  const { createPoller } = require("../src/poller");
  const J = (o) => ({ ok: true, json: async () => o, text: async () => JSON.stringify(o) });
  const X = (t) => ({ ok: true, json: async () => { throw new Error("xml"); }, text: async () => t });
  const row = (nm, cu, v, sh) => `<infoTable><nameOfIssuer>${nm}</nameOfIssuer><cusip>${cu}</cusip><value>${v}</value><shrsOrPrnAmt><sshPrnamt>${sh}</sshPrnamt><sshPrnamtType>SH</sshPrnamtType></shrsOrPrnAmt></infoTable>`;
  const book = (v) => `<x>${row("APPLE INC", "037833100", v, 1e6)}${row("MICRON TECHNOLOGY INC", "595112103", v / 2, 5e5)}</x>`;
  let amendA = false;   // flips to stage a late HR/A for fund A's Q2
  const sub = (pfx, amended) => J({ name: "X", filings: { recent: amended
    ? { form: ["13F-HR/A", "13F-HR", "13F-HR"], accessionNumber: [pfx + "-26-000009", pfx + "-26-000002", pfx + "-26-000001"],
        filingDate: ["2026-08-18", "2026-08-14", "2026-05-15"], reportDate: ["2026-06-30", "2026-06-30", "2026-03-31"] }
    : { form: ["13F-HR", "13F-HR"], accessionNumber: [pfx + "-26-000002", pfx + "-26-000001"],
        filingDate: ["2026-08-14", "2026-05-15"], reportDate: ["2026-06-30", "2026-03-31"] } } });
  const idx = J({ directory: { item: [{ name: "primary_doc.xml", size: 9 }, { name: "infotable.xml", size: 999 }] } });
  const extFetch = async (url) => {
    if (url.includes("company_tickers")) return J({});
    if (url.includes("submissions/CIK0000000401")) return sub("0401", amendA);
    if (url.includes("submissions/CIK0000000402")) return sub("0402", false);
    if (url.includes("infotable.xml")) return X(book(url.includes("000009") ? 999e6 : 800e6));
    if (url.includes("/index.json")) return idx;
    return { ok: false, status: 404, error: "404" };
  };
  const store = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null,
    saveWhale: () => {}, loadWhale: () => null };
  const p = createPoller({ dex: "xyz", store, log: () => {}, version: "test", crypto: false, extFetch });
  p.hydrateWhaleNow();
  const NOWG = Date.UTC(2026, 7, 16, 12);   // in-grace clock, so the window builder creates the Q2 season
  p.whaleAdd(401, "Alpha One LP", NOWG); p.whaleAdd(402, "Beta Two LLC", NOWG);
  await p.whalePull("ALPHA"); await p.whalePull("BETA");
  p.whaleAdd(999, "NoBook Yet LP", NOWG);   // watched, never filed
  let s = await p.getWhaleSeasonQ("Q2 2026");
  assert.ok(s.ok && s.filedN === 2 && s.watchN === 3 && s.agg.nFunds === 2, "baseline: 2/3, one bookless in missing");
  assert.deepEqual(s.missing, ["NOBOOK"]);
  // THE screenshot bug: remove a covered fund AFTER the quarter closed. The window builder has
  // rolled to Q3 and will never look back — the sync must rebuild Q2 to the live list anyway.
  p.whaleRm("BETA");   // real clock: post-grace
  s = await p.getWhaleSeasonQ("Q2 2026");
  assert.equal(s.filedN, 1, "header filedN follows the live list");
  assert.equal(s.watchN, 2, "watchN is the list you can SEE, not a dead build's");
  assert.equal(s.agg.nFunds, 1, "lane denominators agree with the header");
  assert.deepEqual(s.agg.roster.map((r) => r.key), ["ALPHA"], "grid roster too");
  assert.deepEqual(s.missing, ["NOBOOK"], "missing lists only CURRENT bookless watched funds — a removed fund can never haunt it");
  assert.equal(s.amended, false, "roster edits never claim an amendment");
  assert.equal(s.stale, null, "nothing to disclose — the build matches the list, so the chip is silent");
  // Late HR/A on the CLOSED quarter: the daily amendment poll ingests it; the sync must rebuild
  // and NOW the amendment flag is earned.
  amendA = true;
  await p.whaleTickNow(Date.now() + 26 * 3600e3);   // past the slow gate: submissions re-checked, HR/A ingested through the scheduled path
  s = await p.getWhaleSeasonQ("Q2 2026");
  assert.equal(s.amended, true, "a FILING moved — the flag is earned, via the closed-quarter sync");
  assert.ok(Math.abs((s.agg.bought.concat(s.agg.sold).reduce((a2, r) => a2 + Math.abs(r.net), 0)) - 0) >= 0, "agg recomputed without throwing");
  // All coverage removed: the season is KEPT as labeled history (the -18-02 doctrine), chip live.
  p.whaleRm("ALPHA");
  s = await p.getWhaleSeasonQ("Q2 2026");
  assert.ok(s.ok, "kept — history is not destroyed to avoid a label");
  assert.ok(s.stale && s.stale.dropped.includes("ALPHA"), "and the chip says exactly what it is");
});

// ================================================================================================
// FOCUS chart: session-scoped VWAP and frozen geometry (build 2026.08.19-04)
// ------------------------------------------------------------------------------------------------
// The reported defect: a session's VWAP and its frozen 1H HI/LO kept drawing after that session had
// closed — the blue line accumulated straight through the overnight into the next pre-market, and
// the dashed lines spanned the full 72h in BOTH directions, including hours before the range they
// describe existed. These tests execute the real client functions against real bar fixtures; a
// string pin would have passed the whole time the bug was on screen (the -84 lesson).
// ================================================================================================
const FOCCH_SRC = (() => {
  const fs = require("fs"), path = require("path");
  const app = fs.readFileSync(path.join(__dirname, "..", "public", "app.js"), "utf8");
  const grab = (name) => {
    const i = app.indexOf("function " + name + "(");
    assert.ok(i > -1, name + " present in app.js");
    let d = 0;
    for (let k = app.indexOf("{", i); k < app.length; k++) {
      if (app[k] === "{") d++; else if (app[k] === "}") { d--; if (!d) return app.slice(i, k + 1); }
    }
    throw new Error("unbalanced " + name);
  };
  return { app, grab };
})();
// One fixture, shared: a 5m tape running Monday night -> Tuesday cash -> Tuesday night -> Wednesday
// pre-market -> Wednesday cash. Frozen clock (wall-clock independence): every boundary is derived
// from these constants, never from Date.now().
const FOCCH_FIX = (() => {
  const M = 60000, H = 3600000;
  const tueOpen = Date.UTC(2026, 7, 18, 13, 30);           // 09:30 ET
  const tueClose = tueOpen + 6.5 * H;                       // 16:00 ET
  const wedOpen = tueOpen + 24 * H, wedClose = tueClose + 24 * H;
  const sessions = [{ open: tueOpen, close: tueClose }, { open: wedOpen, close: wedClose }];
  // 5m bars from 12h before Tuesday's open to 1h after Wednesday's open. Price and volume vary per
  // bar so a VWAP that failed to reset would land on a visibly different number than one that did.
  const base = [];
  for (let t = tueOpen - 12 * H; t <= wedOpen + 1 * H; t += 5 * M) {
    const i = (t - (tueOpen - 12 * H)) / (5 * M);
    const px = 100 + (i % 17), vol = 10 + (i % 7);
    base.push([t, px, px + 1, px - 1, px, vol]);
  }
  return { M, H, tueOpen, tueClose, wedOpen, wedClose, sessions, base };
})();
function focchApi(sessions, day, tf) {
  const { grab } = FOCCH_SRC;
  const src = grab("focChartSessions") + "\n" + grab("focSessIdx") + "\n" + grab("focSessSpan") + "\n"
    + grab("focRuns") + "\n" + grab("focAgg") + "\n" + grab("focAggCached");
  const FOC = { data: sessions ? { sessions } : {} };
  const FOCCH = { tf, day, base: FOCCH_FIX.base, agg: null };
  const api = new Function("FOC", "FOCCH", src
    + "\n;return { focChartSessions, focSessIdx, focSessSpan, focRuns, focAgg, focAggCached, FOCCH };")(FOC, FOCCH);
  return api;
}

test("FOCUS chart -04: the VWAP is PER SESSION — it dies at its own close and re-anchors at the next open", () => {
  const F = FOCCH_FIX;
  const api = focchApi(F.sessions, { open: F.tueOpen, close: F.tueClose }, 15);
  const { bars, vwapS } = api.focAggCached();
  assert.ok(bars.length > 100, "fixture aggregated to a real bar array");
  const at = (t) => { const i = bars.findIndex((b) => b[0] === t); assert.ok(i > -1, "bar at " + t); return i; };
  // Before Tuesday's open: no session, no VWAP. (This part was already right; it must stay right.)
  assert.equal(vwapS[at(F.tueOpen - 2 * F.H)], null, "pre-market has no VWAP");
  assert.equal(vwapS[at(F.tueOpen - 15 * F.M)], null, "the bar before the open has no VWAP");
  // Inside Tuesday: live.
  assert.ok(vwapS[at(F.tueOpen)] != null, "the opening bar anchors the run");
  assert.ok(vwapS[at(F.tueOpen + 2 * F.H)] != null, "mid-session VWAP is live");
  // THE BUG. Every one of these was a real number before this build.
  assert.equal(vwapS[at(F.tueClose)], null, "the closing bucket ends the session — no VWAP AT the close");
  assert.equal(vwapS[at(F.tueClose + 30 * F.M)], null, "post-market: the session is over, the line is gone");
  assert.equal(vwapS[at(F.tueOpen + 18 * F.H)], null, "overnight: no VWAP survives the night");
  assert.equal(vwapS[at(F.wedOpen - 30 * F.M)], null, "next pre-market: yesterday's VWAP does not lead into today");
  // Wednesday re-anchors at ITS open, carrying nothing from Tuesday.
  const wI = at(F.wedOpen), wb = bars[wI];
  assert.ok(vwapS[wI] != null, "Wednesday's opening bar anchors a NEW run");
  const ownTypical = (wb[2] + wb[3] + wb[4]) / 3;
  assert.ok(Math.abs(vwapS[wI] - ownTypical) < 1e-9,
    `first bar of a session VWAPs to its own typical price (${vwapS[wI]} vs ${ownTypical}) — a carried-over run could not`);
  // And the whole invariant, stated once: a VWAP point can never land where the shading is dark.
  const sess = api.focChartSessions();
  for (let i = 0; i < bars.length; i++) {
    if (vwapS[i] != null) assert.ok(api.focSessIdx(sess, bars[i][0]) >= 0,
      "VWAP point at " + new Date(bars[i][0]).toISOString() + " sits outside every cash window");
  }
});

test("FOCUS chart -04: nulls BREAK the VWAP path — the overnight is a gap, never a straight line across it", () => {
  const F = FOCCH_FIX;
  const api = focchApi(F.sessions, { open: F.tueOpen, close: F.tueClose }, 15);
  const { bars, vwapS } = api.focAggCached();
  const runs = api.focRuns(vwapS, 0, bars.length);
  assert.equal(runs.length, 2, "two sessions on the tape -> two strokes, not one continuous line");
  const spanOf = (r) => [bars[r[0][0]][0], bars[r[r.length - 1][0]][0]];
  const [a0, a1] = spanOf(runs[0]), [b0, b1] = spanOf(runs[1]);
  assert.ok(a0 === F.tueOpen && a1 < F.tueClose, "run 1 is Tuesday's cash window and nothing else");
  assert.ok(b0 === F.wedOpen && b1 <= F.wedClose, "run 2 starts at Wednesday's open");
  assert.ok(a1 < b0, "the runs do not touch — the gap between them is the night");
  // Mutation guard: a path that merely SKIPS nulls yields one run and would bridge the gap.
  const naive = [];
  for (let i = 0; i < bars.length; i++) if (vwapS[i] != null) naive.push(i);
  assert.ok(naive.length > runs[0].length, "the skip-nulls path would have joined the two sessions into one stroke");
});

test("FOCUS chart -04: frozen 1H geometry is clipped to its OWN session, in both directions", () => {
  const F = FOCCH_FIX;
  const api = focchApi(F.sessions, { open: F.tueOpen, close: F.tueClose }, 15);
  const { bars } = api.focAggCached();
  const [i0, i1] = api.focSessSpan(bars, F.tueOpen, F.tueClose);
  assert.ok(i0 > 0, "the span does not start at index 0 — the lines no longer reach back before the open");
  assert.ok(i1 < bars.length - 1, "the span does not end at the last bar — the lines no longer run to the right edge");
  assert.equal(bars[i0][0], F.tueOpen, "the clip starts exactly at the open");
  assert.ok(bars[i1][0] < F.tueClose && bars[i1][0] + 15 * F.M >= F.tueClose, "and ends on the last bucket inside the close");
  // A viewport that contains no bar of that session draws NOTHING — the old code pinned the dashes
  // to the view edges regardless of where the session was.
  const night = bars.filter((b) => b[0] > F.tueClose && b[0] < F.wedOpen);
  assert.ok(night.length > 10, "fixture really has an overnight stretch");
  assert.deepEqual(api.focSessSpan(night, F.tueOpen, F.tueClose), [-1, -1],
    "session off screen -> no span -> no line");
  // A session still running (close in the future) clips to the last bar it has, not to nothing.
  const [w0, w1] = api.focSessSpan(bars, F.wedOpen, F.wedClose);
  assert.ok(w0 > -1 && bars[w1][0] === bars[bars.length - 1][0], "a live session runs to the last bar on the tape");
});

test("FOCUS chart -04: with no calendar windows the chart degrades to the record's own session, never to a blank", () => {
  const F = FOCCH_FIX;
  const api = focchApi(null, { open: F.tueOpen, close: F.tueClose }, 15);   // payload without sessions
  const sess = api.focChartSessions();
  assert.equal(sess.length, 1, "one window, from the record itself");
  assert.equal(sess[0].open, F.tueOpen);
  assert.equal(sess[0].close, F.tueClose);
  const { bars, vwapS } = api.focAggCached();
  const at = (t) => bars.findIndex((b) => b[0] === t);
  assert.ok(vwapS[at(F.tueOpen + F.H)] != null, "the VWAP still draws inside the charted session");
  assert.equal(vwapS[at(F.tueClose + F.H)], null, "and still dies at the close — the fallback is not a licence to run forever");
  // A record with no close (live session, close not yet known) runs open-ended rather than empty.
  const live = focchApi(null, { open: F.tueOpen, close: null }, 15);
  assert.equal(live.focChartSessions()[0].close, Infinity, "an unknown close is open-ended, not zero");
  const lv = live.focAggCached();
  assert.ok(lv.vwapS[lv.bars.length - 1] != null, "so the live run reaches the last bar");
});

test("FOCUS chart -04: the aggregate cache re-keys on the session list, so a calendar refresh cannot serve a stale VWAP", () => {
  const F = FOCCH_FIX;
  const api = focchApi(F.sessions, { open: F.tueOpen, close: F.tueClose }, 15);
  const first = api.focAggCached();
  assert.ok(api.focAggCached() === first, "same tf + same windows -> the cached object, not a rebuild");
  assert.ok(typeof first.sn === "string" && first.sn.includes(String(F.tueOpen)), "the cache key carries the windows");
});

test("FOCUS chart -04: client manifest — the session helpers exist exactly once and the draw path uses them", () => {
  const { app } = FOCCH_SRC;
  for (const name of ["focChartSessions", "focSessIdx", "focSessSpan", "focRuns"]) {
    const n = (app.match(new RegExp("^function " + name + "\\(", "gm")) || []).length;
    assert.equal(n, 1, `${name} defined exactly once (found ${n})`);
  }
  const draw = app.slice(app.indexOf("function focChartDraw("), app.indexOf("function focChartDraw(") + 9000);
  assert.ok(draw.includes("focSessSpan(bars,"), "the clip span is computed by the shared helper, not re-derived inline");
  assert.ok(draw.includes("focRuns(vwapS,"), "the VWAP is stroked as runs");
  assert.ok(draw.includes("const refLine=(v,col,lab,clip)=>") && !draw.includes("const refLine=(v,col,lab)=>"),
    "refLine takes a clip flag — the unclipped edge-to-edge signature is gone");
  assert.ok(!/const sess=\(FOC\.data&&FOC\.data\.sessions\)/.test(draw),
    "the shading reads the shared window list — one definition, so shading and VWAP can never disagree");
});

// ================================================================================================
// FOCUS: session OPEN / CLOSE columns + touch reorder (build 2026.08.19-05)
// ------------------------------------------------------------------------------------------------
// The close is the one number on this board that CANNOT be shown early: it is a measurement of a
// finished session, and the live price is not a stand-in for it. These tests execute the real close
// read, the real fill gate and the real column builders — the failure mode being guarded against is
// a close column that quietly renders the after-hours tape, or the live mark, as "the 16:00 print".
// ================================================================================================
function focus05CloseRig(opts) {
  const o = opts || {};
  const { createPoller } = require("../src/poller");
  const base = { loadAll: () => new Map(), loadRegime: () => [], loadLedger: () => null,
    saveLedger: () => {}, insert: () => {}, saveRegime: () => {}, saveNews: () => {}, loadNews: () => null };
  const M = 60000, OPEN = Date.UTC(2026, 7, 14, 13, 30), CLOSE = OPEN + 390 * M;   // Fri 09:30 -> 16:00 ET
  // 390 in-session 1m bars walking 100 -> 139, then an AFTER-HOURS tape at a wildly different price.
  // If the close read is bounded by the session the after-hours bars can never reach the column; if
  // it is bounded by "the last bar before now" they will, and the test says so.
  const bars = [];
  for (let i = 0; i < 390; i++) { const px = 100 + i / 10; bars.push([OPEN + i * M, px, px + 0.5, px - 0.5, px, 1000]); }
  for (let i = 0; i < 60; i++) bars.push([CLOSE + i * M, 400, 401, 399, 400, 500]);
  const lane = { posted: o.posted == null ? 390 : o.posted };   // in-session bars the 1m writer has flushed
  const dark = o.dark || [];                                    // tickers whose lane landed nothing (mutable: the caller may darken a seat after the stamp)
  const store = { ...base, saveFocus: () => {}, loadFocus: () => null, candlesEnabled: () => o.archive !== false,
    readCandles: () => [],
    readCandles1m: (coin, lo, hi) => {
      if (dark.includes(String(coin).split(":")[1])) return [];
      return bars.slice(0, lane.posted).concat(bars.slice(390)).filter((k) => k[0] >= lo && k[0] <= hi);
    } };
  const p = createPoller({ dex: "xyz", store, log: () => {}, version: "test" });
  const spine = (px) => { const a = []; for (let i = 48; i >= 0; i--) a.push({ t: OPEN - i * 3600e3, o: px, h: px * 1.01, l: px * 0.99, c: px, v: 1e6 }); return a; };
  for (const [t, px] of [["BE", 100], ["NVDA", 900], ["MU", 100], ["AMD", 150], ["LLY", 800],
    ["TSLA", 300], ["XOM", 110], ["JPM", 200], ["COIN", 250], ["PLTR", 60]])
    p.seedRowNow("xyz:" + t, { ticker: t, uni: "xyz", px, vol: 9e6, oi: 9e6, oiBase: 1000, hourlyRaw: spine(px) });
  p.focusTickNow(OPEN + 5 * M);
  return { p, OPEN, CLOSE, M, lane, bars };
}

test("focus -05: the close fills at 16:00 from the session's OWN last bar — never the after-hours tape", () => {
  const { p, OPEN, CLOSE, M } = focus05CloseRig();
  assert.ok(p.getFocus(OPEN + 5 * M).today, "the stamp lands");
  assert.equal(p.getFocus(OPEN + 5 * M).today.closedAt, 0, "nothing is closed at 09:35");
  // Mid-session: the tick runs, and the close still does not exist. This is the whole point of the
  // column — a dash here is the truth, and any number would be a fabrication.
  p.focusTickNow(OPEN + 200 * M);
  const mid = p.getFocus(OPEN + 200 * M).today;
  assert.equal(mid.closedAt, 0, "the close does not fill mid-session");
  for (const r of mid.rows) assert.equal(r.closePx, undefined, "…and no row carries a closePx yet");

  p.focusTickNow(CLOSE + 2 * M);
  const rec = p.getFocus(CLOSE + 2 * M).today;
  assert.ok(rec.closedAt, "the fill lands once the session is over");
  assert.equal(rec.closeNote, null, "a complete lane claims no shortfall");
  for (const r of rec.rows) {
    assert.ok(Math.abs(r.closePx - 138.9) < 1e-6, `the 15:59 print, not the 400 after-hours tape (got ${r.closePx})`);
    assert.equal(r.closeCov.inWin, 390, "measured over the whole cash window");
    assert.equal(r.closeCov.slopMin, 1, "one bar-width of slop on a complete lane");
  }
  // Frozen: a later tick, with the after-hours tape now much longer, must not restate it.
  p.focusTickNow(CLOSE + 55 * M);
  assert.ok(Math.abs(p.getFocus(CLOSE + 55 * M).today.rows[0].closePx - 138.9) < 1e-6,
    "a filled close never moves again — geometry is frozen at the fill, not recomputed per tick");
});

test("focus -05: a lane short of the close HOLDS the fill, and the wait is bounded", () => {
  const a = focus05CloseRig({ posted: 387 });          // writer stalled at 15:56
  a.p.focusTickNow(a.CLOSE + 1 * a.M);
  assert.equal(a.p.getFocus(a.CLOSE + a.M).today.closedAt, 0,
    "a lane four minutes short of 16:00 does NOT close — that print is not the close");
  // The bar lands inside the grace: the fill takes the real one.
  a.lane.posted = 390;
  a.p.focusTickNow(a.CLOSE + 2 * a.M);
  const ok = a.p.getFocus(a.CLOSE + 2 * a.M).today;
  assert.ok(ok.closedAt && ok.closeNote === null, "the wait pays off — a complete close, no disclosure needed");
  assert.ok(Math.abs(ok.rows[0].closePx - 138.9) < 1e-6, "and it is the 15:59 print");

  const b = focus05CloseRig({ posted: 387 });          // writer never recovers
  b.p.focusTickNow(b.CLOSE + 1 * b.M);
  assert.equal(b.p.getFocus(b.CLOSE + b.M).today.closedAt, 0, "held inside the grace");
  b.p.focusTickNow(b.CLOSE + 6 * b.M);                 // past close +5m
  const rec = b.p.getFocus(b.CLOSE + 6 * b.M).today;
  assert.ok(rec.closedAt, "the wait is bounded — the record closes rather than dashing forever");
  assert.match(rec.closeNote, /did not reach the close/, "…and states it instead of implying a 16:00 print");
  assert.equal(rec.rows[0].closeCov.slopMin, 4, "the shortfall rides the row, per seat, forever");
});

test("focus -05: a seat with no bars dashes and does not hold the others hostage", () => {
  const dark = [];
  const { p, OPEN, CLOSE, M } = focus05CloseRig({ dark });
  dark.push(p.getFocus(OPEN + 5 * M).today.rows[0].ticker);   // darken a seat that actually took one
  p.focusTickNow(CLOSE + 1 * M);
  const rec = p.getFocus(CLOSE + M).today;
  assert.ok(rec.closedAt, "an absent lane is not a late one — it must not hold the fill open");
  const dry = rec.rows.filter((r) => r.closePx == null);
  assert.ok(dry.length >= 1 && dry.every((r) => r.closeCov.bars === 0),
    "the dark seat carries an honest null with its coverage attached");
  assert.ok(rec.rows.filter((r) => r.closePx != null).length >= 1, "…while every other seat closed normally");
});

test("focus -05: with the archive disabled the close is refused out loud, never guessed from the mark", () => {
  const { p, CLOSE, M } = focus05CloseRig({ archive: false });
  p.focusTickNow(CLOSE + 1 * M);
  const rec = p.getFocus(CLOSE + M).today;
  assert.ok(rec.closedAt, "the record still closes — the state machine does not stall on a disabled archive");
  assert.match(rec.closeNote, /archive disabled/, "and says why every close is a dash");
  for (const r of rec.rows) assert.equal(r.closePx, null, "not one price is invented from the live mark");
});

test("focus -05: sessionCloseStats is bounded by the window at BOTH ends", () => {
  const { sessionCloseStats } = require("../src/compute");
  const M = 60000, O = 1000000, C = O + 10 * M;
  const bars = [];
  for (let i = -5; i < 15; i++) bars.push([O + i * M, 10 + i, 11 + i, 9 + i, 10 + i, 100]);
  const s = sessionCloseStats(bars, O, C);
  assert.equal(s.closePx, 19, "the last bar INSIDE the window (t = close - 1m), not the tape beyond it");
  assert.equal(s.openPx, 10, "the first bar inside it, not the pre-market ones before");
  assert.equal(s.bars, 10, "exactly the ten in-window bars");
  assert.equal(s.slopMs, M, "one bar of slop on a complete window");
  // Unsorted input must not change the answer — the archive is not guaranteed ordered.
  const shuffled = bars.slice().reverse();
  assert.equal(sessionCloseStats(shuffled, O, C).closePx, 19, "order of the input does not decide the close");
  assert.equal(sessionCloseStats([], O, C), null, "no bars -> null, never a zero");
  assert.equal(sessionCloseStats(bars, C, O), null, "an inverted window is refused rather than guessed");
  // A window whose last bar sits well short of the close reports the gap rather than hiding it.
  const short = bars.filter((b) => b[0] < C - 4 * M);
  assert.equal(sessionCloseStats(short, O, C).slopMs, 5 * M, "the slop is the evidence the close is not the close");
});

// ---- the two columns, executed ------------------------------------------------------------------
function focColsApi() {
  const fs = require("fs"), path = require("path");
  const app = fs.readFileSync(path.join(__dirname, "..", "public", "app.js"), "utf8");
  const grab = (name) => {
    const i = app.indexOf("function " + name + "(");
    assert.ok(i > -1, name + " present in app.js");
    let d = 0;
    for (let k = app.indexOf("{", i); k < app.length; k++) {
      if (app[k] === "{") d++; else if (app[k] === "}") { d--; if (!d) return app.slice(i, k + 1); }
    }
    throw new Error("unbalanced " + name);
  };
  const i0 = app.indexOf("const FOC_COLS=[");
  assert.ok(i0 > -1, "FOC_COLS present");
  const i1 = app.indexOf("\n];", i0);
  const cols = app.slice(i0, i1 + 3);
  const src = grab("esc") + "\n" + grab("focPx") + "\n" + grab("focSgn") + "\n" + grab("focCls") + "\n"
    + grab("focNa") + "\n" + grab("focDry") + "\n" + grab("focCol") + "\n" + grab("focMoveCol") + "\n" + cols;
  return new Function("FOC", "focChips", "liveMark", "focPrefsSave", src
    + "\n;return { FOC_COLS, focCol, focMoveCol };");
}
function focCols(FOC, saved) {
  return focColsApi()(FOC, () => "", () => null, () => { if (saved) saved.n++; });
}

test("focus -05: the CLOSE column tells 'not yet' apart from 'closed, and this seat had nothing'", () => {
  const FOC = { _day: { closedAt: 0 } };
  const api = focCols(FOC);
  const col = api.focCol("close");
  assert.ok(col, "the CLOSE column exists");
  const row = { ticker: "NBIS", prevClose: 268.18, h1: { openPx: 268.83 } };

  // Mid-session: a pending cell, and NOT a dash — "the session has not closed" is a different
  // statement from "no data", and collapsing them is the category error this column must avoid.
  const pending = col.td(row);
  assert.match(pending, /at close/, "before 16:00 the cell says the close is still ahead");
  assert.ok(!/\u2014<\/span>/.test(pending), "…and does not render the na dash, which would mean something else");
  assert.ok(!/268|241/.test(pending), "no price of any kind stands in for a close that does not exist");

  // Closed, seat had no bars: now it IS a dash, and the dash carries its own reason.
  FOC._day = { closedAt: 1 };
  const dark = col.td({ ...row, closePx: null, closeCov: { bars: 0, inWin: 0, slopMin: null } });
  assert.match(dark, /—/, "a closed session with no bars is an honest dash");
  assert.match(dark, /landed nothing/, "…and says which of the two silences this was");

  // Closed with a print: the number, plus the move off THIS session's open.
  const done = col.td({ ...row, closePx: 237.60, closeCov: { bars: 390, inWin: 390, slopMin: 1 } });
  assert.match(done, /237\.60/, "the close price renders");
  assert.match(done, /-11\.6%/, "with the move from the 268.83 open, signed");
  assert.match(done, /neg/, "and coloured by that move");
  assert.ok(!/lane did not reach/.test(done), "a complete lane makes no shortfall claim");

  // A short lane still shows its number, but discloses the gap and dims it.
  const short = col.td({ ...row, closePx: 237.60, closeCov: { bars: 386, inWin: 386, slopMin: 4 } });
  assert.match(short, /4m before 16:00/, "a close read off a short lane says so on the cell");
  assert.match(short, /class="dim"/, "…and is visually demoted rather than presented as the 16:00 print");
});

test("focus -05: the OPEN column is the 09:30 archive print, and sorts on it", () => {
  const api = focCols({ _day: { closedAt: 0 } });
  const col = api.focCol("open");
  assert.ok(col && col.h1, "OPEN rides the h1 record, so it forms and freezes with the rest");
  const row = { ticker: "NBIS", prevClose: 268.18, h1: { openPx: 268.83, hi: 274.91, lo: 262.17 } };
  const cell = col.td(row);
  assert.match(cell, /268\.83/, "the opening print renders");
  assert.match(cell, /\+0\.2% from the 268\.18 prev close/, "hover carries the realised gap");
  assert.equal(col.sv(row), 268.83, "sortable on the open itself");
  assert.equal(col.sv({ ticker: "X" }), null, "no h1 -> no sort value, never a zero");
  assert.match(col.td({ ticker: "X" }), /—/, "…and no h1 renders the dash with its coverage reason");
  // Once the close exists the open's tooltip carries the day's whole move, from one measurement.
  assert.match(col.td({ ...row, closePx: 237.60 }), /closed -11\.6% off it/, "the day's move, off the open");
});

test("focus -05: focMoveCol is the ONE reorder, shared by the mouse and touch paths", () => {
  const saved = { n: 0 };
  const FOC = { order: ["ticker", "why", "px", "open", "close", "gap"], _day: null };
  const api = focCols(FOC, saved);
  assert.ok(api.focMoveCol("close", "px", true), "a column moves before its target");
  assert.deepEqual(FOC.order, ["ticker", "why", "close", "px", "open", "gap"]);
  assert.equal(saved.n, 1, "…and the new order is persisted, once");
  assert.ok(api.focMoveCol("close", "gap", false), "and after it, on the other side of the drop");
  assert.deepEqual(FOC.order, ["ticker", "why", "px", "open", "gap", "close"]);
  // The refusals. Each of these was a way to corrupt the order or lose a column entirely.
  assert.equal(api.focMoveCol("px", "px", true), false, "a column cannot be dropped on itself");
  assert.equal(api.focMoveCol("px", "ticker", true), false, "the locked TICKER column is not a drop target");
  assert.equal(api.focMoveCol("px", "nope", true), false, "an unknown target moves nothing");
  assert.equal(api.focMoveCol(null, "px", true), false, "no drag key, no move");
  assert.deepEqual(FOC.order, ["ticker", "why", "px", "open", "gap", "close"], "every refusal left the order intact");
  assert.equal(saved.n, 2, "and no refusal wrote to storage");
});

test("focus -05: manifest — close fill wired into the tick, touch reorder wired into the header", () => {
  const fs = require("fs"), path = require("path");
  const rd = (f) => fs.readFileSync(path.join(__dirname, "..", f), "utf8");
  const app = rd("public/app.js"), pol = rd("src/poller.js"), css = rd("public/styles.css");
  for (const pin of ["function closeFocus(", "const FOCUS_CLOSE_GRACE", "const FOCUS_CLOSE_SLOP",
    "if (held && now >= sess.close) closeFocus(focusState, now);",
    "closedAt: 0, closeNote: null, closeLate: 0"])
    assert.ok(pol.includes(pin), "poller pin: " + pin);
  assert.ok(pol.includes("store.readCandles1m(p.coin, st.open - 1, st.close + 1)"),
    "the close read is bounded by the record's own session, not by now");
  for (const pin of ["function focMoveCol(", "function focWireTouchDrag(", "const FOC_HOLD_MS",
    "th.addEventListener('pointerdown'", "th.setPointerCapture(pid)", "{k:'open', label:'OPEN'", "{k:'close', label:'CLOSE'"])
    assert.ok(app.includes(pin), "client pin: " + pin);
  assert.equal((app.match(/focMoveCol\(/g) || []).length, 3,
    "one definition of focMoveCol plus exactly two call sites: the mouse drop and the touch drop");
  assert.ok(!/FOC\.order\.splice\(/.test(app),
    "no caller splices the column order directly — every reorder goes through the one validated mutation");
  assert.ok(app.includes("if(!c||c.nosort||_focDragK) return;"), "a drag in flight is never also a sort");
  assert.ok(css.includes(".foctbl th[data-fock]") && css.includes("touch-action:pan-y"),
    "the header opts out of the long-press callout while the board stays scrollable");
});

// ================================================================================================
// FOCUS: the LATE close fill (build 2026.08.19-06)
// ------------------------------------------------------------------------------------------------
// -05 shipped a close that could only fill while the record sat in the live slot: between 16:00 ET
// and the 00:00 UTC retire — four hours in EDT, three in EST. A deploy inside that window lost the
// session's close permanently, which is exactly what happened on 2026-08-19. The correction is that
// this read was never time-sensitive: it is bounded by the record's own open and close, so taking it
// at 21:00 returns what taking it at 16:01 would have. These tests pin that equivalence directly —
// the late fill must be byte-identical to the on-time one, or the fix is a different measurement.
// ================================================================================================
test("focus -06: a record that retired unfilled still gets its close, and it is the SAME read", () => {
  const M = 60000;
  // On time: the fill lands in the live slot at 16:02.
  const a = focus05CloseRig();
  a.p.focusTickNow(a.CLOSE + 2 * M);
  const onTime = a.p.getFocus(a.CLOSE + 2 * M).today;
  assert.ok(onTime.closedAt, "baseline: the on-time fill lands");
  assert.equal(onTime.closeLate, 0, "and does not claim to be late");

  // Late: nothing ticks until 21:12 ET — past the 00:00 UTC retire, so the record is in `prev`.
  const b = focus05CloseRig();
  const LATE = Date.UTC(2026, 7, 20, 1, 12);          // 2026-08-19 21:12 ET, the screenshot's clock
  assert.ok(LATE > b.CLOSE, "the late tick really is after the close");
  b.p.focusTickNow(LATE);
  const d = b.p.getFocus(LATE);
  assert.equal(d.today, null, "the record has retired out of the live slot");
  assert.ok(d.prev && d.prev.closedAt, "…and the retired record fills anyway — this is the -05 bug");
  assert.ok(d.prev.closeLate > 300, "the record discloses how late the read was taken");
  // THE EQUIVALENCE. Same window, same bars, same answer — the only difference is the disclosure.
  assert.deepEqual(d.prev.rows.map((r) => r.closePx), onTime.rows.map((r) => r.closePx),
    "the late read returns exactly the on-time read — the window is the record's, not the clock's");
  assert.deepEqual(d.prev.rows.map((r) => r.closeCov.inWin), onTime.rows.map((r) => r.closeCov.inWin),
    "…including per-seat coverage");
  assert.deepEqual(d.prev.rows.map((r) => r.closeCov.bars), onTime.rows.map((r) => r.closeCov.bars),
    "…and the RAW read count: a late fill that widened its window to `now` would sweep the "
    + "after-hours tape into the coverage even though the price came out right");
  assert.equal(d.prev.closeNote, null, "a complete lane read late still claims no shortfall");
  // Idempotent: a filled record is never re-read, however many ticks follow.
  const px = d.prev.rows[0].closePx, at = d.prev.closedAt;
  b.p.focusTickNow(LATE + 30 * M);
  const again = b.p.getFocus(LATE + 30 * M).prev;
  assert.equal(again.rows[0].closePx, px, "a filled close never moves again");
  assert.equal(again.closedAt, at, "…and the fill is not re-stamped on every tick");
});

test("focus -06: the late fill runs on weekends — a Friday close missed at 16:00 lands on Saturday", () => {
  const M = 60000;
  const { p, CLOSE } = focus05CloseRig();             // Friday 2026-08-14
  const SAT = Date.UTC(2026, 7, 15, 18, 0);           // Saturday 14:00 ET — no session at all
  p.focusTickNow(SAT);
  const d = p.getFocus(SAT);
  assert.equal(d.state, "offday", "it really is a non-session day");
  assert.ok(d.prev && d.prev.closedAt,
    "the fill runs BEFORE the session lookup returns early — otherwise Friday waits for Monday and dies");
  assert.ok(Math.abs(d.prev.rows[0].closePx - 138.9) < 1e-6, "and it is Friday's 15:59 print");
  assert.ok(d.prev.closeLate > (SAT - CLOSE) / M - 5, "disclosed as the day-late read it is");
});

test("focus -06: the late fill reaches the prior slot ONLY — it never walks back through history", () => {
  const fs = require("fs"), path = require("path");
  const pol = fs.readFileSync(path.join(__dirname, "..", "src", "poller.js"), "utf8");
  const tick = pol.slice(pol.indexOf("function focusTick(nowInj)"), pol.indexOf("function focusTick(nowInj)") + 3000);
  assert.equal((tick.match(/closeFocus\(/g) || []).length, 2, "exactly two fills: the live record and the prior slot");
  assert.ok(tick.includes("closeFocus(focusPrev, now)") && tick.includes("closeFocus(focusState, now)"),
    "one call per slot, each naming its record explicitly");
  assert.ok(!/closedAt\s*&&/.test(tick) && !/!\w+\.closedAt/.test(tick),
    "neither call site re-checks closedAt — the guard lives inside closeFocus, where a test can reach it");
  assert.ok(tick.indexOf("closeFocus(focusPrev, now)") < tick.indexOf("const sess = marketSessions"),
    "the prior-slot fill sits above the session lookup, so a weekend cannot skip it");
  assert.ok(!/focusPrev\s*=\s*\w+\.prev/.test(pol.slice(pol.indexOf("function closeFocus("), pol.indexOf("function closeFocus(") + 2500)),
    "the fill mutates the record it was handed and reaches for no other");
});

test("focus -06: the CLOSE cell stops promising a fill once the session is over", () => {
  const row = { ticker: "NBIS", prevClose: 268.18, h1: { openPx: 268.83 } };
  const CLOSE = Date.UTC(2026, 7, 14, 20, 0);

  // Session still running: the promise is honest, so it stands.
  const live = focColsApi()({ _day: { closedAt: 0, close: Date.now() + 3600e3 } }, () => "", () => null, () => {});
  assert.match(live.focCol("close").td(row), /at close/, "before 16:00 the cell still says the close is ahead");

  // Session over, never filled: a dash that names the silence, not a promise nobody will keep.
  const dead = focColsApi()({ _day: { closedAt: 0, close: CLOSE } }, () => "", () => null, () => {});
  const cell = dead.focCol("close").td(row);
  assert.ok(!/at close/.test(cell), "a finished session never claims a fill is still coming");
  assert.match(cell, /—/, "it is a dash");
  assert.match(cell, /without its close ever being measured/, "…that says exactly which silence this is");
  assert.ok(!/268|241|237/.test(cell), "and still no price stands in for the close that was missed");

  // Filled late: the number, plus the disclosure that the read was taken hours after the fact.
  const late = focColsApi()({ _day: { closedAt: 1, close: CLOSE, closeLate: 312 } }, () => "", () => null, () => {});
  const lc = late.focCol("close").td({ ...row, closePx: 237.60, closeCov: { bars: 390, inWin: 390, slopMin: 1 } });
  assert.match(lc, /237\.60/, "the late-filled close renders normally");
  assert.match(lc, /read 312m after the close/, "…with when it was read stated on the cell");
  assert.match(lc, /-11\.6%/, "and the move off the open is unchanged by the lateness");
});
